insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('session-agenda-and-priorities-sheet', 'Session Agenda and Priorities Sheet', 'worksheet'::resource_kind, 'A short sheet for client and clinician to set the session agenda together.', 'Use it to open a session with a shared plan instead of guessing where to start.', array['Adults', 'Teens']::text[], 'Five minutes', 'Hand this over in the first minute of a session so the client has a hand in shaping it. It works well for clients who tend to bury the thing they most want to talk about until the last five minutes, or who show up without a clear sense of what they need that day. Ranking items by weight, not just listing them, is the part clients skip if you do not prompt for it.', '[{"id": "f0", "type": "textarea", "label": "What has happened since we last met that you want to make sure we cover?"}, {"id": "f1", "type": "textarea", "label": "List up to three things you could talk about today."}, {"id": "f2", "type": "textarea", "label": "Which one matters most right now, and why?"}, {"id": "f3", "type": "textarea", "label": "Is there anything you would rather leave for another day?"}, {"id": "f4", "type": "textarea", "label": "What would make today feel like it was worth the hour?"}]'::jsonb, array['session structure', 'goal setting']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('family-genogram-sketch', 'Family Genogram Sketch', 'worksheet'::resource_kind, 'A guided sheet for sketching three generations of family relationships and patterns.', 'Use it to map family structure, roles and recurring patterns for case formulation.', array['Adults', 'Teens']::text[], 'One session', 'Draw the shapes together on a blank page rather than handing over a printed template; the act of building it out loud surfaces detail a form would miss. Ask about closeness, conflict and cutoff between people, not just who is related to whom, and note repeating patterns across generations, such as who tends to caretake or who tends to leave. Keep the focus on structure and pattern, not on assigning blame to any one relative.', '[{"id": "f0", "type": "textarea", "label": "Who is in your immediate family, and how would you describe each relationship in one word?"}, {"id": "f1", "type": "textarea", "label": "Who else has mattered to you growing up, inside or outside the family?"}, {"id": "f2", "type": "textarea", "label": "Where do you see closeness in the family? Where do you see distance or conflict?"}, {"id": "f3", "type": "textarea", "label": "Are there patterns that seem to repeat across generations, like divorce, addiction or estrangement?"}, {"id": "f4", "type": "textarea", "label": "What role do you tend to play in the family, and has that role changed over time?"}]'::jsonb, array['formulation', 'family']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('sleep-habits-and-wind-down-log', 'Sleep Habits and Wind-Down Log', 'worksheet'::resource_kind, 'A one-week log for tracking bedtime routine, sleep timing and morning alertness.', 'Use it to spot habits that are keeping sleep light, late or interrupted.', array['Adults', 'Teens']::text[], 'One week', 'This is a plain observation log, not a sleep study; the point is to make a week of habits visible rather than relied-on memory. Watch for screens, caffeine timing and inconsistent wake times more than for the number of hours logged. Clients who insist their sleep is fine often find the log tells a different story once they see a week laid out side by side.', '[{"id": "f0", "type": "textarea", "label": "Monday: bedtime, wake time, and how rested you felt on waking."}, {"id": "f1", "type": "textarea", "label": "Tuesday: bedtime, wake time, and how rested you felt on waking."}, {"id": "f2", "type": "textarea", "label": "Wednesday: bedtime, wake time, and how rested you felt on waking."}, {"id": "f3", "type": "textarea", "label": "Thursday: bedtime, wake time, and how rested you felt on waking."}, {"id": "f4", "type": "textarea", "label": "Friday: bedtime, wake time, and how rested you felt on waking."}, {"id": "f5", "type": "textarea", "label": "Saturday and Sunday: bedtime, wake time, and how rested you felt on waking."}, {"id": "f6", "type": "textarea", "label": "What did the week show you about your wind-down routine?"}]'::jsonb, array['sleep', 'self-monitoring', 'routines']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('end-of-therapy-reflection-sheet', 'End-of-Therapy Reflection Sheet', 'worksheet'::resource_kind, 'A closing worksheet for reviewing progress and planning for life after therapy ends.', 'Use it to mark what changed, name remaining risks, and plan how to keep gains going.', array['Adults', 'Teens', 'Groups']::text[], 'One session', 'Save this for the last session or two rather than handing it out cold; clients often need a nudge to notice change that happened gradually. Naming early warning signs and a plan for them matters as much as celebrating progress, since relapse of old patterns is common and normal after ending care. Leave room for ambivalence about ending; wanting to stop and being nervous about stopping usually coexist.', '[{"id": "f0", "type": "textarea", "label": "What is different now compared to when you started?"}, {"id": "f1", "type": "textarea", "label": "Which skill or idea from our work together do you use the most?"}, {"id": "f2", "type": "textarea", "label": "What still feels shaky or unfinished?"}, {"id": "f3", "type": "textarea", "label": "What are your early warning signs that things are slipping?"}, {"id": "f4", "type": "textarea", "label": "What is your plan if those signs show up?"}, {"id": "f5", "type": "textarea", "label": "Who or what can you lean on if you need support after ending here?"}]'::jsonb, array['session structure', 'relapse prevention']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('weekly-goals-and-barriers-tracker', 'Weekly Goals and Barriers Tracker', 'worksheet'::resource_kind, 'A repeating one-week sheet for setting a small goal and naming what might get in the way.', 'Use it to build the habit of planning for obstacles before they derail a goal.', array['Adults', 'Teens']::text[], 'Ongoing, weekly', 'Keep the weekly goal small enough that it is genuinely achievable in a normal week; overreaching is the most common way this tracker fails. The barrier column is the part that does the real work, since naming a likely obstacle in advance makes it far easier to plan around than discovering it mid-week. Review last week''s sheet at the start of the next session before starting a new one.', '[{"id": "f0", "type": "textarea", "label": "This week, what is one goal you want to make progress on?"}, {"id": "f1", "type": "textarea", "label": "What could get in the way of that goal this week?"}, {"id": "f2", "type": "textarea", "label": "What is your plan if that obstacle shows up?"}, {"id": "f3", "type": "textarea", "label": "How will you know by the end of the week whether you made progress?"}, {"id": "f4", "type": "textarea", "label": "Looking back, what actually happened?"}]'::jsonb, array['goal setting', 'planning']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('situation-thought-feeling-behavior-chart', 'Situation-Thought-Feeling-Behavior Chart', 'cbt'::resource_kind, 'A four-column chart that teaches the basic cognitive model with a client''s own example.', 'Use it to introduce how situations, thoughts, feelings and behavior connect.', array['Adults', 'Teens']::text[], '20 minutes', 'This is the psychoeducation piece before a full thought record, best used the first time a client is introduced to the cognitive model. Walk through one recent, specific moment together rather than asking for a general pattern, since a single concrete example makes the links between the four columns click faster than an abstract explanation. Once a client can fill this in unprompted, they are usually ready for more detailed thought-work tools.', '[{"id": "f0", "type": "textarea", "label": "Describe one specific recent situation."}, {"id": "f1", "type": "textarea", "label": "What thought went through your mind in that moment?"}, {"id": "f2", "type": "textarea", "label": "What feeling came with that thought, and how strong was it, 0 to 10?"}, {"id": "f3", "type": "textarea", "label": "What did you do next?"}, {"id": "f4", "type": "textarea", "label": "Looking at all four boxes together, what do you notice?"}]'::jsonb, array['core CBT', 'psychoeducation', 'automatic thoughts']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('cognitive-distortions-checklist', 'Cognitive Distortions Checklist', 'cbt'::resource_kind, 'A plain-language checklist of common unhelpful thinking patterns to spot in daily thoughts.', 'Use it to build a client''s ear for their own recurring thinking patterns.', array['Adults', 'Teens']::text[], '15 minutes', 'Give the client a recent thought and have them check every pattern that seems to fit rather than forcing a single label; several often overlap in one thought. The value is in recognition, not labeling the thought as bad, and a lighter tone here helps, since clients often enjoy naming their own mind''s favorite tricks once the shame is taken out of it. Revisit the checklist across sessions to see which patterns show up most.', '[{"id": "f0", "type": "textarea", "label": "Write down one thought you have had recently that felt sticky or upsetting."}, {"id": "f1", "type": "textarea", "label": "Does it jump to the worst outcome? Check yes or no and explain."}, {"id": "f2", "type": "textarea", "label": "Does it treat a feeling as if it were a fact?"}, {"id": "f3", "type": "textarea", "label": "Does it use words like always, never, or everyone?"}, {"id": "f4", "type": "textarea", "label": "Does it predict the future as if it were certain?"}, {"id": "f5", "type": "textarea", "label": "Which pattern shows up most often for you, based on this and past weeks?"}]'::jsonb, array['thinking traps', 'automatic thoughts', 'core CBT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('behavior-experiment-design-sheet', 'Behavior Experiment Design Sheet', 'cbt'::resource_kind, 'A structured sheet for designing a small real-world test of a belief before and after it runs.', 'Use it to turn a client''s prediction into a testable, time-limited experiment.', array['Adults', 'Teens']::text[], '20 minutes, plus the experiment itself', 'The prediction has to be specific and falsifiable, or the experiment will not teach anything; push back gently if a client writes something too vague to be tested. Keep the first experiment small and low-stakes so it is likely to actually happen. The review section at the end matters more than the plan, since it is where the gap between prediction and outcome does the work.', '[{"id": "f0", "type": "textarea", "label": "What belief or prediction do you want to test?"}, {"id": "f1", "type": "textarea", "label": "What specific action will you take to test it?"}, {"id": "f2", "type": "textarea", "label": "What do you predict will happen, in detail?"}, {"id": "f3", "type": "textarea", "label": "How confident are you in that prediction, 0 to 100?"}, {"id": "f4", "type": "textarea", "label": "What actually happened when you tried it?"}, {"id": "f5", "type": "textarea", "label": "What does the outcome tell you about the original belief?"}]'::jsonb, array['behavioral experiment', 'core CBT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('thought-vs-fact-sorting-card', 'Thought vs Fact Sorting Card', 'cbt'::resource_kind, 'A short in-session card for sorting a list of statements into thoughts and facts.', 'Use it to strengthen the basic skill of telling a thought apart from a fact.', array['Adults', 'Teens', 'Groups']::text[], 'Ten minutes', 'This is a warm-up exercise, useful before deeper cognitive work with a client who tends to treat every thought as automatically true. Mix in a few statements that are genuinely factual along with opinions and predictions, so the sorting is not a trick question. If a client struggles, ask what evidence would prove the statement true in a courtroom sense; that framing often clarifies the line quickly.', '[{"id": "f0", "type": "textarea", "label": "Write three thoughts you have had this week about yourself, others, or the future."}, {"id": "f1", "type": "textarea", "label": "For each one, mark it as a thought or a fact, and explain your reasoning."}, {"id": "f2", "type": "textarea", "label": "For any you marked as facts, what evidence supports that?"}, {"id": "f3", "type": "textarea", "label": "For any you marked as thoughts, how might a friend see it differently?"}]'::jsonb, array['core CBT', 'automatic thoughts']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('weekly-automatic-thought-tally', 'Weekly Automatic Thought Tally', 'cbt'::resource_kind, 'A simple week-long tally of how often a few common automatic thoughts show up.', 'Use it to track the frequency of unhelpful thoughts over time, not just their content.', array['Adults', 'Teens']::text[], 'One week', 'This trades depth for frequency: instead of writing out a full thought record every time, the client makes a quick mark each time a familiar thought shows up. It works well for clients who find full thought records tedious or who need to see change in volume over several weeks rather than in a single entry. Compare tallies week to week rather than judging any single day.', '[{"id": "f0", "type": "textarea", "label": "List up to three thoughts you want to track this week."}, {"id": "f1", "type": "textarea", "label": "Monday through Wednesday: tally marks for each thought."}, {"id": "f2", "type": "textarea", "label": "Thursday through Saturday: tally marks for each thought."}, {"id": "f3", "type": "textarea", "label": "Sunday: tally marks for each thought."}, {"id": "f4", "type": "textarea", "label": "What changed compared to last week''s tally, if you have one?"}]'::jsonb, array['automatic thoughts', 'self-monitoring']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('tug-of-war-with-the-struggle-monster', 'Tug-of-War With the Struggle Monster', 'act'::resource_kind, 'A metaphor exercise about dropping the rope in a tug-of-war with a difficult feeling.', 'Use it to introduce the idea of stopping the struggle instead of winning it.', array['Adults', 'Teens']::text[], '15 minutes', 'Walk the metaphor through slowly: a monster on one end of a rope, the client pulling with all their strength, exhausted and no closer to winning. Ask what happens to the pulling, not the monster, if the client simply drops the rope. This lands best after a client has already described a struggle they keep losing to, so the metaphor maps onto something real rather than staying abstract.', '[{"id": "f0", "type": "textarea", "label": "What feeling or thought have you been in a tug-of-war with lately?"}, {"id": "f1", "type": "textarea", "label": "What does \"pulling harder\" look like for you in real life?"}, {"id": "f2", "type": "textarea", "label": "What has pulling harder actually gotten you?"}, {"id": "f3", "type": "textarea", "label": "What would \"dropping the rope\" look like, practically, this week?"}, {"id": "f4", "type": "textarea", "label": "What are you afraid would happen if you dropped it?"}]'::jsonb, array['metaphor', 'core ACT', 'willingness']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('sushi-train-of-thoughts-practice', 'Sushi Train of Thoughts Practice', 'act'::resource_kind, 'A defusion exercise imagining thoughts passing by on a conveyor belt to be watched, not grabbed.', 'Use it to practice noticing thoughts without acting on every one that passes.', array['Adults', 'Teens']::text[], 'Ten minutes', 'Guide the client to picture each thought as a small plate going past on a conveyor belt: some plates look tempting, some look unpleasant, and the instruction either way is to watch rather than grab. This is easiest to teach after a short stretch of quiet in the room, so the thoughts have something to arrive against. Some clients prefer the plates on a treadmill; adjust the image to whatever sticks for them.', '[{"id": "f0", "type": "textarea", "label": "Sit quietly for two minutes and notice the thoughts that pass through your mind."}, {"id": "f1", "type": "textarea", "label": "What did you notice yourself wanting to grab onto?"}, {"id": "f2", "type": "textarea", "label": "What happened when you let a thought pass without grabbing it?"}, {"id": "f3", "type": "textarea", "label": "How is this different from your usual way of relating to thoughts?"}]'::jsonb, array['defusion', 'core ACT', 'metaphor']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('values-vs-goals-sorting-sheet', 'Values vs Goals Sorting Sheet', 'act'::resource_kind, 'A worksheet that separates a client''s values, which are directions, from their goals, which are destinations.', 'Use it to clarify the difference between an ongoing direction and a finishable target.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients often confuse the two, listing goals as values or treating values as things to finish and check off. Use the compass-versus-destination framing: a value like being a caring friend never gets "completed," while a goal like calling a friend today does. This sheet works well as a bridge into any values-based planning that follows, since it clears up the confusion before it derails later work.', '[{"id": "f0", "type": "textarea", "label": "List three things that matter to you, without worrying yet whether they are values or goals."}, {"id": "f1", "type": "textarea", "label": "For each one, ask: can this ever be finished and checked off? If yes, it is likely a goal."}, {"id": "f2", "type": "textarea", "label": "Sort your list into values and goals based on that question."}, {"id": "f3", "type": "textarea", "label": "Pick one value. What is one small goal this week that would move you in that direction?"}]'::jsonb, array['values', 'core ACT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('committed-action-weekly-planner', 'Committed Action Weekly Planner', 'act'::resource_kind, 'A repeating weekly sheet for planning one values-based action and reviewing how it went.', 'Use it to build a habit of small, regular action in line with a client''s stated values.', array['Adults', 'Teens']::text[], 'Ongoing, weekly', 'This is the follow-through piece after values work: a small planned action, tied explicitly to a named value, reviewed the next week. Keep the action modest and specific rather than aspirational, since the point is building a pattern of action over months, not a single impressive week. When an action does not happen, treat it as information about barriers rather than a failure to correct with more willpower.', '[{"id": "f0", "type": "textarea", "label": "Which value does this week''s action connect to?"}, {"id": "f1", "type": "textarea", "label": "What specific action will you take, and when?"}, {"id": "f2", "type": "textarea", "label": "What might get in the way?"}, {"id": "f3", "type": "textarea", "label": "Did the action happen? What actually occurred?"}, {"id": "f4", "type": "textarea", "label": "What did you learn for next week''s plan?"}]'::jsonb, array['committed action', 'values']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('present-moment-senses-anchor', 'Present Moment Senses Anchor', 'act'::resource_kind, 'A brief five-senses exercise for making contact with the present moment in session.', 'Use it to practice shifting attention from thought to direct present-moment experience.', array['Adults', 'Teens', 'Groups']::text[], 'Five minutes', 'Use this as a short reset at any point a client seems pulled entirely into thought, worry or story. Go slowly through each sense rather than rushing to the next, since the value is in dwelling in direct experience, not completing a checklist. This is a present-moment contact exercise rather than a crisis tool, though the two families of skill can look similar in practice.', '[{"id": "f0", "type": "textarea", "label": "Name three things you can see right now."}, {"id": "f1", "type": "textarea", "label": "Name two things you can hear right now."}, {"id": "f2", "type": "textarea", "label": "Name one thing you can feel physically right now, like your feet on the floor."}, {"id": "f3", "type": "textarea", "label": "What shifted, if anything, after doing this?"}]'::jsonb, array['present moment', 'core ACT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('what-and-how-mindfulness-skills-card', 'What and How Mindfulness Skills Card', 'dbt'::resource_kind, 'A reference card teaching the DBT what skills and how skills of mindfulness practice.', 'Use it to teach observing, describing and participating, done nonjudgmentally and one thing at a time.', array['Adults', 'Teens', 'Groups']::text[], '15 minutes', 'Introduce the what skills, observe, describe, and participate, as three things a client can do with attention, then the how skills, nonjudgmentally, one-mindfully, and effectively, as the manner of doing them. A short in-session practice, like eating a raisin slowly or listening to one sound fully, makes the six skills land better than explaining them in the abstract. Return to this card whenever a client''s mindfulness practice needs a refresher.', '[{"id": "f0", "type": "textarea", "label": "Pick one small activity, like drinking water or walking down a hallway."}, {"id": "f1", "type": "textarea", "label": "Practice it while observing, describing to yourself, and fully participating."}, {"id": "f2", "type": "textarea", "label": "Practice it again while staying nonjudgmental, one-mindful, and effective."}, {"id": "f3", "type": "textarea", "label": "What was different about doing it this way?"}]'::jsonb, array['core DBT', 'mindfulness']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('emotion-vulnerability-factors-log', 'Emotion Vulnerability Factors Log', 'dbt'::resource_kind, 'A daily log tracking the physical and situational factors that make emotions harder to regulate.', 'Use it to spot the sleep, food, illness and stress factors that raise a client''s emotional baseline.', array['Adults', 'Teens']::text[], 'One week', 'This is a precursor to full emotion regulation work: before addressing a reaction to a specific event, it helps to know whether a client was already running on empty. Track the same handful of factors daily, sleep, meals, physical illness, and substance use, alongside the day''s hardest emotional moment. Patterns usually appear within a week, and clients are often surprised how much a skipped meal or short night explains.', '[{"id": "f0", "type": "textarea", "label": "How many hours did you sleep last night?"}, {"id": "f1", "type": "textarea", "label": "Did you eat regular meals today? Yes, no, or partly."}, {"id": "f2", "type": "textarea", "label": "Were you dealing with any physical illness or pain today?"}, {"id": "f3", "type": "textarea", "label": "What was the hardest emotional moment of your day?"}, {"id": "f4", "type": "textarea", "label": "Looking at the whole week, which factor seems to matter most for you?"}]'::jsonb, array['emotion regulation', 'self-monitoring']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('turning-the-mind-practice', 'Turning the Mind Practice', 'dbt'::resource_kind, 'A short practice for choosing acceptance of a hard reality, moment by moment, without pretending to like it.', 'Use it to practice the repeated choice to accept a fact rather than fight it.', array['Adults', 'Teens']::text[], 'Ten minutes', 'Explain that turning the mind is a repeated choice, like standing at a fork in the road and turning toward acceptance each time the mind wanders back toward fighting reality, not a single decision made once. It does not require agreeing with or liking the situation, only ceasing the fight against the fact that it is happening. Clients often need to hear that turning the mind may need to happen dozens of times about the same fact before it feels steady.', '[{"id": "f0", "type": "textarea", "label": "What is a hard reality you find yourself fighting against right now?"}, {"id": "f1", "type": "textarea", "label": "What does \"fighting it\" look like for you, in thoughts or actions?"}, {"id": "f2", "type": "textarea", "label": "Practice turning your mind toward accepting the fact, just for this moment. What happened?"}, {"id": "f3", "type": "textarea", "label": "What would change if you kept choosing this, even without liking it?"}]'::jsonb, array['radical acceptance', 'core DBT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('willingness-vs-willfulness-check', 'Willingness vs Willfulness Check', 'dbt'::resource_kind, 'A short check-in for noticing when a client has shifted from willingness into willfulness.', 'Use it to help a client recognize digging in against reality versus working with it.', array['Adults', 'Teens']::text[], 'Ten minutes', 'Willfulness looks like refusing to do what is needed, giving up, or insisting on being right even when it costs more than it gains; willingness looks like doing what the moment calls for, even reluctantly. Use a recent example rather than a hypothetical one, and avoid moralizing the willful moment, since clients usually already know it did not serve them. The goal is recognition in the moment, which takes repeated practice to build.', '[{"id": "f0", "type": "textarea", "label": "Describe a recent situation where things did not go the way you wanted."}, {"id": "f1", "type": "textarea", "label": "Looking back, did you respond with willingness or willfulness?"}, {"id": "f2", "type": "textarea", "label": "What signs tell you which one it was?"}, {"id": "f3", "type": "textarea", "label": "What would a willing response have looked like instead?"}]'::jsonb, array['dialectics', 'core DBT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('self-validation-before-action-card', 'Self-Validation Before Action Card', 'dbt'::resource_kind, 'A short prompt card for practicing validating one''s own emotional reaction before problem-solving it.', 'Use it to build the habit of validating a reaction before trying to change or fix it.', array['Adults', 'Teens']::text[], 'Ten minutes', 'Many clients move straight to fixing or judging an emotional reaction without ever acknowledging that it made sense given the situation; this card slows that down. Model the language out loud first, since self-validation can feel foreign or self-indulgent to clients who were taught to dismiss their own reactions. Note that validating the reaction is separate from agreeing the resulting action was the best choice.', '[{"id": "f0", "type": "textarea", "label": "What emotional reaction are you being hard on yourself about?"}, {"id": "f1", "type": "textarea", "label": "Given the situation, how does that reaction make sense?"}, {"id": "f2", "type": "textarea", "label": "Write one sentence validating the reaction, starting with \"It makes sense that...\""}, {"id": "f3", "type": "textarea", "label": "Now that it is validated, is there anything you still want to work on or change?"}]'::jsonb, array['emotion regulation', 'self-compassion']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('pursue-withdraw-cycle-map', 'Pursue-Withdraw Cycle Map', 'couples'::resource_kind, 'A worksheet for mapping the pursue-and-withdraw pattern a couple falls into during conflict.', 'Use it to help both partners see the cycle as the shared problem, not the other person.', array['Couples']::text[], '30 minutes', 'Draw the cycle as a loop on paper with both partners present: one partner''s pursuit triggers the other''s withdrawal, and that withdrawal triggers more pursuit, round and round. The reframe that matters most is naming the cycle itself as the enemy, not either partner''s behavior in isolation. Expect some resistance to this framing at first, since each partner usually arrives certain the other one started it.', '[{"id": "f0", "type": "textarea", "label": "Partner A: when do you notice yourself pursuing, and what does it look like?"}, {"id": "f1", "type": "textarea", "label": "Partner B: when do you notice yourself withdrawing, and what does it look like?"}, {"id": "f2", "type": "textarea", "label": "What usually triggers the first move in the cycle?"}, {"id": "f3", "type": "textarea", "label": "What does each of you feel underneath the pursuing or withdrawing?"}, {"id": "f4", "type": "textarea", "label": "What would help you both step out of the cycle earlier next time?"}]'::jsonb, array['relationship issues', 'conflict', 'pattern']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('attachment-injury-timeline', 'Attachment Injury Timeline', 'couples'::resource_kind, 'A guided sheet for identifying a specific past moment that damaged trust between partners.', 'Use it to name a wounding moment clearly enough to work on repairing it.', array['Couples']::text[], 'One session', 'An attachment injury is a specific moment, not a general pattern, often a time one partner needed the other and felt abandoned or betrayed in a way that still colors the relationship. Slow the pace here; this exercise can bring up strong feelings, and rushing to resolution before both partners feel heard tends to backfire. The goal of this sheet is naming the injury clearly, not resolving it in one sitting.', '[{"id": "f0", "type": "textarea", "label": "Partner A: is there a specific moment that still feels unresolved between you? Describe it."}, {"id": "f1", "type": "textarea", "label": "What did you need in that moment that you did not get?"}, {"id": "f2", "type": "textarea", "label": "Partner B: what is it like to hear this moment described?"}, {"id": "f3", "type": "textarea", "label": "What would help Partner A feel that moment is being taken seriously now?"}]'::jsonb, array['trust', 'repair', 'EFT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('forgiveness-readiness-scale', 'Forgiveness Readiness Scale', 'couples'::resource_kind, 'A short scale for each partner to privately rate where they stand on working toward forgiveness.', 'Use it to open an honest conversation about readiness without pressuring either partner.', array['Couples']::text[], '20 minutes', 'Have each partner fill this out separately before comparing, since social pressure to say "I forgive you" too soon can bury real ambivalence. A low number is useful information, not a failure, and naming what is missing gives the couple something concrete to work toward rather than a vague expectation of moving on. Revisit the scale over weeks rather than expecting it to shift in one conversation.', '[{"id": "f0", "type": "textarea", "label": "On a scale of 0 to 10, where do you feel you are in working toward forgiveness?"}, {"id": "f1", "type": "textarea", "label": "What would need to happen for that number to move up?"}, {"id": "f2", "type": "textarea", "label": "What are you afraid would happen if you forgave too soon?"}, {"id": "f3", "type": "textarea", "label": "What do you need from your partner right now, regardless of where the number sits?"}]'::jsonb, array['repair', 'trust']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('household-team-meeting-agenda', 'Household Team Meeting Agenda', 'couples'::resource_kind, 'A short weekly agenda template for a couple to run their household like a working team.', 'Use it to keep logistics conversations short, regular and separate from emotional processing time.', array['Couples']::text[], '20 minutes, weekly', 'Logistics conversations that happen only when something has gone wrong tend to turn into conflict; a standing short meeting for scheduling and chores takes that pressure off other conversations. Keep this meeting strictly practical, and if deeper relationship issues come up, note them for another time rather than letting the agenda balloon. Consistency matters more than length here.', '[{"id": "f0", "type": "textarea", "label": "What is on the calendar this week that needs coordinating?"}, {"id": "f1", "type": "textarea", "label": "What household tasks need to be divided or caught up on?"}, {"id": "f2", "type": "textarea", "label": "Is anything feeling unfair in the current division of tasks?"}, {"id": "f3", "type": "textarea", "label": "One thing to appreciate about how the other partner handled something this week."}]'::jsonb, array['household', 'communication']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('post-conflict-debrief-worksheet', 'Post-Conflict Debrief Worksheet', 'couples'::resource_kind, 'A structured sheet for reviewing a past argument together once both partners have cooled down.', 'Use it to extract what a conflict revealed, once emotions have settled enough to look at it.', array['Couples']::text[], '30 minutes', 'Wait until well after the argument has cooled, ideally a day later, rather than debriefing while either partner is still flooded. The point is not re-litigating who was right, but noticing what each person needed underneath the fight and what each contributed to how it escalated. Coach both partners to speak about their own part before commenting on the other''s.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what did you need in that moment that you did not ask for directly?"}, {"id": "f1", "type": "textarea", "label": "Partner A: what did you do that made things harder?"}, {"id": "f2", "type": "textarea", "label": "Partner B: what did you need in that moment that you did not ask for directly?"}, {"id": "f3", "type": "textarea", "label": "Partner B: what did you do that made things harder?"}, {"id": "f4", "type": "textarea", "label": "What would you both do differently if a similar moment came up again?"}]'::jsonb, array['conflict', 'repair']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('all-about-me-poster-craft', 'All About Me Poster Craft', 'kids'::resource_kind, 'A first-sessions poster where a child draws and writes about themselves to build rapport.', 'Use it to get to know a child and build comfort in the therapy space.', array['Children']::text[], '30 minutes', 'This works best in the first session or two, before diving into any harder material, and gives a quieter child something concrete to do with their hands while talking. A parent can help gather photos or favorite items ahead of time if the clinician wants to send a note home first. Keep the tone light and curious; this is rapport-building, not assessment.', '[{"id": "f0", "type": "textarea", "label": "Draw a picture of yourself in the middle of the page."}, {"id": "f1", "type": "textarea", "label": "Write or draw three things you like to do."}, {"id": "f2", "type": "textarea", "label": "Write or draw the people and pets in your life."}, {"id": "f3", "type": "textarea", "label": "Write or draw one thing you are really good at."}, {"id": "f4", "type": "textarea", "label": "Write or draw one thing you hope happens by coming here."}]'::jsonb, array['children', 'play']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('calm-down-corner-design-craft', 'Calm Down Corner Design Craft', 'kids'::resource_kind, 'A craft where a child designs a calm-down space for home, with the parent helping set it up.', 'Use it to give a child ownership over a physical space for settling down.', array['Children']::text[], '30 minutes', 'Have the child draw or describe their ideal calm corner first, then talk with the parent about what is realistic to set up at home, even if it is just a cushion in a corner. Emphasize that this is a place to go to feel better, never a punishment or a time-out spot, and the child should be able to choose to use it. Check back in a few sessions later on whether the corner got built and used.', '[{"id": "f0", "type": "textarea", "label": "Draw or describe a cozy, calm spot you would want in your home."}, {"id": "f1", "type": "textarea", "label": "What would you want to have there, like pillows, books, or toys?"}, {"id": "f2", "type": "textarea", "label": "What could you do there when you feel upset?"}, {"id": "f3", "type": "textarea", "label": "Parent: where in the home could a space like this actually go?"}]'::jsonb, array['children', 'self-soothing']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('session-rules-poster-craft', 'Session Rules Poster Craft', 'kids'::resource_kind, 'A craft where a child helps create and decorate the ground rules for their therapy sessions.', 'Use it to give a child a sense of ownership and predictability in the therapy space.', array['Children']::text[], '20 minutes', 'Keep the list short, three to five rules the child helps phrase in their own words, covering things like respect, safety, and what happens with anything they share. This is also a natural moment to explain confidentiality and its limits in plain, age-appropriate language the child can understand and refer back to. Post the finished poster somewhere visible in future sessions.', '[{"id": "f0", "type": "textarea", "label": "What is one rule that would help our time together feel safe?"}, {"id": "f1", "type": "textarea", "label": "What is one rule about being kind to each other?"}, {"id": "f2", "type": "textarea", "label": "Decorate the poster with colors or pictures."}, {"id": "f3", "type": "textarea", "label": "Is there anything you are curious or nervous about, about coming here?"}]'::jsonb, array['children', 'session structure']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('my-body-owners-manual-craft', 'My Body Owner''s Manual Craft', 'kids'::resource_kind, 'A craft where a child describes what their body needs to feel good, like sleep, movement and rest.', 'Use it to build a child''s awareness of their own basic care needs.', array['Children']::text[], '30 minutes', 'Frame this around function and care, not appearance: what the body needs to have energy, feel calm, and get through the day well. This works well alongside sleep or routine work with a parent present to help fill in realistic details. Keep language strictly about needs like rest, movement, and food timing, never about size, weight or how the body looks.', '[{"id": "f0", "type": "textarea", "label": "Draw an outline of your body and label parts that help you move, think, or rest."}, {"id": "f1", "type": "textarea", "label": "What helps your body feel rested?"}, {"id": "f2", "type": "textarea", "label": "What helps your body feel calm when it is upset?"}, {"id": "f3", "type": "textarea", "label": "What does your body need more of, based on a normal week?"}]'::jsonb, array['children', 'routines']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('kindness-tracker-chart-craft', 'Kindness Tracker Chart Craft', 'kids'::resource_kind, 'A craft chart where a child tracks small acts of kindness given and received over a week.', 'Use it to build a child''s awareness of prosocial behavior in both directions.', array['Children']::text[], 'One week', 'Have the child decorate the chart first, then add a sticker or mark each time they notice an act of kindness, either one they did or one someone did for them. This works well for children building social skills or self-esteem, since it broadens attention beyond only moments that went wrong. Review the chart together the following week rather than checking in daily.', '[{"id": "f0", "type": "textarea", "label": "Decorate your kindness chart with colors or stickers."}, {"id": "f1", "type": "textarea", "label": "Monday and Tuesday: write or draw one kind thing you did or noticed."}, {"id": "f2", "type": "textarea", "label": "Wednesday and Thursday: write or draw one kind thing you did or noticed."}, {"id": "f3", "type": "textarea", "label": "Friday through Sunday: write or draw one kind thing you did or noticed."}, {"id": "f4", "type": "textarea", "label": "What did you notice about doing this for a week?"}]'::jsonb, array['children', 'self-esteem']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('group-trust-web-game', 'Group Trust Web Game', 'game'::resource_kind, 'A group game where a ball of yarn is passed around while sharing, building a visible web of connection.', 'Use it to build group cohesion and a felt sense of connection early in group work.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Sitting or standing in a circle, one person holds the end of a ball of yarn, shares something brief, then tosses the ball to someone else while keeping hold of the string, building a web across the group. Keep the prompts light for a first group, such as a favorite place or something they are looking forward to, and save deeper prompts for a group that has already met a few times. Debrief by pointing out how the web looks messy but holds together, much like the group.', '[{"id": "f0", "type": "textarea", "label": "Prompt for the round: share one thing about yourself as you toss the yarn."}, {"id": "f1", "type": "textarea", "label": "What did it feel like to see the web build across the group?"}, {"id": "f2", "type": "textarea", "label": "What does the web remind you of about how this group works together?"}, {"id": "f3", "type": "textarea", "label": "What is one thing you want this group to know about you going forward?"}]'::jsonb, array['group', 'connection', 'icebreaker']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('session-check-in-dice-game', 'Session Check-In Dice Game', 'game'::resource_kind, 'A game where rolling a die matches a number to a check-in prompt to open the session.', 'Use it to make opening check-ins more engaging for clients who find them repetitive.', array['Adults', 'Teens', 'Children', 'Groups']::text[], 'Ten minutes', 'Number six prompts one through six and let the client roll to see which they answer; this small element of chance makes an otherwise routine check-in feel less like a chore. It works well at the start of nearly any session and can be reused indefinitely by simply rewriting the prompt list from time to time. In a group, pass the die around so each member answers a different roll.', '[{"id": "f0", "type": "textarea", "label": "Roll 1: how has your week been, in one word?"}, {"id": "f1", "type": "textarea", "label": "Roll 2: what is something that went well recently?"}, {"id": "f2", "type": "textarea", "label": "Roll 3: what has been hard lately?"}, {"id": "f3", "type": "textarea", "label": "Roll 4: what do you want to make sure we talk about today?"}, {"id": "f4", "type": "textarea", "label": "Roll 5: what is your energy level right now, 1 to 10?"}, {"id": "f5", "type": "textarea", "label": "Roll 6: is there anything you are avoiding bringing up?"}]'::jsonb, array['session structure', 'icebreaker']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('feelings-face-match-up-game', 'Feelings Face Match-Up Game', 'game'::resource_kind, 'A memory-style matching game pairing feeling faces with situations that could cause them.', 'Use it to build a client''s vocabulary for naming emotions tied to situations.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Lay out two sets of face-down cards, one with feeling faces and one with short situations, and take turns flipping two at a time looking for a match. There is often more than one reasonable match for a situation card, which is a useful discussion point rather than a problem with the game. This works well for younger clients still building emotional vocabulary, and for groups as a shared warm-up.', '[{"id": "f0", "type": "textarea", "label": "Write or draw six different feeling faces on separate cards."}, {"id": "f1", "type": "textarea", "label": "Write six short situations that could cause a feeling, on separate cards."}, {"id": "f2", "type": "textarea", "label": "Play the matching game, explaining your reasoning for each match."}, {"id": "f3", "type": "textarea", "label": "Was there a situation that could match more than one feeling? Which ones?"}]'::jsonb, array['emotion identification', 'children']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('common-ground-mingle-bingo', 'Common Ground Mingle Bingo', 'game'::resource_kind, 'A group mingling game where members find others who share an experience listed on their bingo card.', 'Use it to build early connection in a group by surfacing shared experiences.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Fill a bingo grid with light, low-pressure prompts, such as "has a pet" or "is working on patience," and have members mingle to find someone matching each square and sign it. This works best in the first few sessions of a group when members are still learning each other''s names and finding common ground lowers early anxiety. Debrief by asking what surprised them about what they shared with others.', '[{"id": "f0", "type": "textarea", "label": "Fill in your bingo card with prompts, or use the ones provided."}, {"id": "f1", "type": "textarea", "label": "Mingle and find someone matching each square; have them sign it."}, {"id": "f2", "type": "textarea", "label": "What did you learn about someone you did not know before?"}, {"id": "f3", "type": "textarea", "label": "What was it like to find something in common with the group?"}]'::jsonb, array['group', 'icebreaker']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('would-you-rather-values-edition', 'Would You Rather: Values Edition', 'game'::resource_kind, 'A discussion game using paired values-based choices to explore what a client prioritizes.', 'Use it to surface a client''s values through playful, low-stakes forced choices.', array['Adults', 'Teens', 'Groups']::text[], '20 minutes', 'Read out a series of would-you-rather pairs built around values rather than trivia, such as more free time or more recognition at work, and have the client choose and explain. The explanation matters more than the choice itself, since it is where the underlying value gets named. In a group, let members compare answers, which often sparks discussion about how differently people weigh the same trade-off.', '[{"id": "f0", "type": "textarea", "label": "Would you rather have more time or more money? Why?"}, {"id": "f1", "type": "textarea", "label": "Would you rather be known for kindness or for achievement? Why?"}, {"id": "f2", "type": "textarea", "label": "Would you rather have one close friend or many acquaintances? Why?"}, {"id": "f3", "type": "textarea", "label": "Would you rather take a safe path or a risky one toward a dream? Why?"}, {"id": "f4", "type": "textarea", "label": "Looking at your answers, what do they say about what you value?"}]'::jsonb, array['values', 'group']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('trauma-timeline-of-safety-and-support', 'Trauma Timeline of Safety and Support', 'worksheet'::resource_kind, 'A timeline worksheet marking moments of safety and support across a client''s life.', 'Use it to build a resource of remembered safety without revisiting traumatic detail.', array['Adults', 'Teens']::text[], '30 minutes', 'Keep this focused strictly on safety and support, people, places, and moments that felt protective, never on the traumatic events themselves. Clients sometimes default to narrating what went wrong; gently redirect back to what and who kept them steady. The finished timeline becomes a resource to return to during grounding work.', '[{"id": "f0", "type": "textarea", "label": "Mark a moment early in life when you felt safe or supported."}, {"id": "f1", "type": "textarea", "label": "Mark a person who has been steady for you, at any point."}, {"id": "f2", "type": "textarea", "label": "Mark a more recent moment of safety or support."}, {"id": "f3", "type": "textarea", "label": "Which of these could you lean on more right now?"}]'::jsonb, array['PTSD and trauma', 'grounding', 'support']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('meaning-and-growth-reflection-after-trauma', 'Meaning and Growth Reflection After Trauma', 'cbt'::resource_kind, 'A reflection worksheet on strengths and changes a client notices in themselves since a hard period.', 'Use it to notice growth and strength without needing to revisit traumatic detail.', array['Adults', 'Teens']::text[], '20 minutes', 'This stays entirely present-focused: what a client notices about themselves now, not an account of what happened. Some clients will not find growth to name yet, and that is a fine answer; do not push for positivity before it is genuine. Use it in the later, more stable stretch of work, not early on.', '[{"id": "f0", "type": "textarea", "label": "What is something you know about your own strength now that you did not before?"}, {"id": "f1", "type": "textarea", "label": "Has anything in your relationships or priorities shifted?"}, {"id": "f2", "type": "textarea", "label": "What would you tell someone else going through something hard?"}, {"id": "f3", "type": "textarea", "label": "What does this tell you about where you are today?"}]'::jsonb, array['PTSD and trauma', 'strengths']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('window-widening-skills-card', 'Window Widening Skills Card', 'dbt'::resource_kind, 'A reference card of skills matched to whether a client is under- or over-aroused after activation.', 'Use it to match a specific skill to whether the body is flooded or shut down.', array['Adults', 'Teens']::text[], '15 minutes', 'Pair this with any existing window-of-tolerance map: once a client can name whether they are above, below, or inside the window, this card gives them a specific next step for each zone, movement and cold water for shutdown, slow breath and grounding for flooding. Practice each skill in session before relying on the card in a hard moment.', '[{"id": "f0", "type": "textarea", "label": "When you feel shut down or numb, which skill from the card will you try?"}, {"id": "f1", "type": "textarea", "label": "When you feel flooded or panicked, which skill from the card will you try?"}, {"id": "f2", "type": "textarea", "label": "What tells your body it has moved back inside the window?"}, {"id": "f3", "type": "textarea", "label": "Which skill felt most doable when you tried it this week?"}]'::jsonb, array['PTSD and trauma', 'grounding', 'core DBT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('rebuilding-physical-closeness-pace-conversation', 'Rebuilding Physical Closeness Pace Conversation', 'couples'::resource_kind, 'A paced conversation guide for a couple navigating physical closeness after trauma.', 'Use it to help both partners agree on pace and cues for physical closeness.', array['Couples']::text[], '30 minutes', 'Keep this conversation about pace, comfort, and signals, never a request to explain or justify why closeness feels hard right now. The partner without trauma history often needs coaching that slowing down is not rejection. Agree on a clear, low-stakes way to pause in the moment that both partners will actually use.', '[{"id": "f0", "type": "textarea", "label": "What kinds of closeness currently feel comfortable?"}, {"id": "f1", "type": "textarea", "label": "What signal will you use if you need to pause?"}, {"id": "f2", "type": "textarea", "label": "Partner: how can you respond supportively if that signal comes up?"}, {"id": "f3", "type": "textarea", "label": "What would feel like a good, manageable next step for you both?"}]'::jsonb, array['PTSD and trauma', 'pacing', 'support']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('my-safety-plan-coloring-page', 'My Safety Plan Coloring Page', 'kids'::resource_kind, 'A coloring page where a child draws people, places and things that help them feel safe.', 'Use it to give a child a visible, personal reminder of safety and support.', array['Children']::text[], '20 minutes', 'Keep this focused on safety, comfort and helpers, never on retelling what happened; a child''s job here is to color and point, not narrate. If a child discloses anything during this activity, pause the craft and follow your state''s mandatory reporting duties before continuing. Send the finished page home with the parent as a visual reminder.', '[{"id": "f0", "type": "textarea", "label": "Color a picture of a safe place."}, {"id": "f1", "type": "textarea", "label": "Draw or write the names of grown-ups who help you feel safe."}, {"id": "f2", "type": "textarea", "label": "Draw something that helps your body feel calm."}, {"id": "f3", "type": "textarea", "label": "Who could you go to if you felt scared or unsafe?"}]'::jsonb, array['PTSD and trauma', 'children', 'grounding']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('worry-outcome-prediction-log', 'Worry Outcome Prediction Log', 'worksheet'::resource_kind, 'A log for predicting a worry''s outcome in advance, then checking it against what actually happened.', 'Use it to build evidence that most predicted worries do not play out as feared.', array['Adults', 'Teens']::text[], 'Two weeks', 'Have the client log a worry and their predicted outcome before the event, then return to the same entry afterward with what actually happened. The pattern across several entries tends to do more convincing than any single one. Review the log together rather than leaving the insight for the client to find alone.', '[{"id": "f0", "type": "textarea", "label": "What are you worried will happen?"}, {"id": "f1", "type": "textarea", "label": "How likely does it feel right now, 0 to 100?"}, {"id": "f2", "type": "textarea", "label": "What actually happened afterward?"}, {"id": "f3", "type": "textarea", "label": "How did the prediction compare to reality?"}]'::jsonb, array['anxiety', 'worry', 'self-monitoring']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('anxiety-fuel-sources-worksheet', 'Anxiety Fuel Sources Worksheet', 'cbt'::resource_kind, 'A worksheet identifying the daily habits, caffeine, sleep and avoidance patterns that feed anxiety.', 'Use it to map the everyday factors that raise or lower a client''s baseline anxiety.', array['Adults', 'Teens']::text[], '20 minutes', 'This widens the lens beyond a single worry to the daily habits quietly raising baseline anxiety, caffeine, screen use before bed, and avoidance that shrinks a client''s world over time. Clients are often surprised how many small factors stack up. Pick one or two to adjust rather than overhauling everything at once.', '[{"id": "f0", "type": "textarea", "label": "What in your daily routine tends to raise your anxiety?"}, {"id": "f1", "type": "textarea", "label": "What tends to lower it, even briefly?"}, {"id": "f2", "type": "textarea", "label": "What are you currently avoiding because of anxiety?"}, {"id": "f3", "type": "textarea", "label": "Which one factor would you like to adjust first?"}]'::jsonb, array['anxiety', 'psychoeducation', 'avoidance']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('anxious-mind-as-overprotective-guard-metaphor', 'Anxious Mind as Overprotective Guard Metaphor', 'act'::resource_kind, 'A metaphor exercise framing anxious thoughts as an overprotective guard doing its job too well.', 'Use it to relate to anxious thoughts with less struggle by seeing their protective intent.', array['Adults', 'Teens']::text[], '15 minutes', 'Introduce the image of an overeager guard who sounds the alarm for everything, even harmless things, because it takes its job of protecting the client seriously. The move is not to fire the guard but to thank it and decide for oneself whether the alarm is worth acting on. This tends to soften the fight clients have with their own anxious mind.', '[{"id": "f0", "type": "textarea", "label": "What does your anxious \"guard\" tend to warn you about most?"}, {"id": "f1", "type": "textarea", "label": "What is it trying to protect you from?"}, {"id": "f2", "type": "textarea", "label": "What would it look like to thank the guard without obeying every alarm?"}, {"id": "f3", "type": "textarea", "label": "What could you do instead, values in hand?"}]'::jsonb, array['anxiety', 'metaphor', 'defusion']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('anxiety-opposite-action-ladder', 'Anxiety Opposite Action Ladder', 'dbt'::resource_kind, 'A stepped ladder for practicing opposite action against anxiety-driven avoidance.', 'Use it to plan graduated steps of approaching what anxiety says to avoid.', array['Adults', 'Teens']::text[], 'One week', 'Build the ladder together, ranking steps from least to most uncomfortable, and confirm the emotion does not fit the actual facts of the situation before assigning opposite action. Start on a low rung and build confidence before moving up. Review what happened after each attempted step, not just whether it was completed.', '[{"id": "f0", "type": "textarea", "label": "What is anxiety telling you to avoid?"}, {"id": "f1", "type": "textarea", "label": "List three to five steps from easiest to hardest toward approaching it."}, {"id": "f2", "type": "textarea", "label": "Which step will you try this week?"}, {"id": "f3", "type": "textarea", "label": "What happened when you tried it?"}]'::jsonb, array['anxiety', 'opposite action', 'exposure']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('worry-whack-a-mole-game', 'Worry Whack-a-Mole Game', 'game'::resource_kind, 'A quick-response game where players respond to popped-up worries with a coping skill before time runs out.', 'Use it to practice quick access to coping skills for common worries in a playful format.', array['Teens', 'Children', 'Groups']::text[], '20 minutes', 'Write common worries on small cards or cups; a player "pops up" a worry and has a short time limit to name a coping skill that fits before the next one appears. Keep the pace brisk and the tone playful, since the point is building quick, almost reflexive access to skills. Debrief by asking which skills came fastest and which felt shakier.', '[{"id": "f0", "type": "textarea", "label": "Write five common worries on separate cards or cups."}, {"id": "f1", "type": "textarea", "label": "For each one popped, name a coping skill within ten seconds."}, {"id": "f2", "type": "textarea", "label": "Which skill came to mind fastest?"}, {"id": "f3", "type": "textarea", "label": "Which worry was hardest to respond to quickly?"}]'::jsonb, array['anxiety', 'coping skills', 'group']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('energy-budget-worksheet', 'Energy Budget Worksheet', 'worksheet'::resource_kind, 'A worksheet for planning a day''s limited energy across tasks that drain and tasks that restore.', 'Use it to plan a realistic day when energy is low rather than overcommitting.', array['Adults', 'Teens']::text[], '15 minutes', 'Treat energy like a limited daily budget rather than an unlimited resource, and have the client list planned tasks alongside their rough energy cost. Low mood often comes with a habit of overcommitting and then feeling like a failure; this worksheet makes the math visible in advance. Build in at least one restoring item, not only obligations.', '[{"id": "f0", "type": "textarea", "label": "List what you need or want to do today."}, {"id": "f1", "type": "textarea", "label": "Next to each, estimate how much energy it will take, low, medium or high."}, {"id": "f2", "type": "textarea", "label": "What is one thing today that will restore energy rather than spend it?"}, {"id": "f3", "type": "textarea", "label": "Does today''s list actually fit your energy budget? What would you cut?"}]'::jsonb, array['depression', 'planning', 'self-monitoring']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('self-criticism-to-self-coaching-rewrite', 'Self-Criticism to Self-Coaching Rewrite', 'cbt'::resource_kind, 'A worksheet rewriting harsh self-critical thoughts into the voice of a firm but fair coach.', 'Use it to shift a client''s inner voice from punishing to firm and workable.', array['Adults', 'Teens']::text[], '20 minutes', 'A coach voice is firm and honest, unlike a purely soft self-compassion voice some clients resist, so it can be an easier bridge for clients who find kindness toward themselves hard to accept. Have the client write the harsh thought first, then rewrite it as something a good coach would actually say, direct but not cruel. Practice saying the rewritten version out loud.', '[{"id": "f0", "type": "textarea", "label": "Write a self-critical thought you have had recently."}, {"id": "f1", "type": "textarea", "label": "What would a firm, fair coach say instead, in that same situation?"}, {"id": "f2", "type": "textarea", "label": "What is the difference in how each version lands?"}, {"id": "f3", "type": "textarea", "label": "Which version would help you actually take the next step?"}]'::jsonb, array['depression', 'self-criticism', 'core CBT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('values-beneath-the-low-mood-practice', 'Values Beneath the Low Mood Practice', 'act'::resource_kind, 'An exercise identifying what a client still cares about even when motivation is absent.', 'Use it to locate values that can guide action even without feeling motivated first.', array['Adults', 'Teens']::text[], '20 minutes', 'Depression often removes the feeling of wanting before it removes what a client actually values, so this exercise separates the two. Ask what would still matter even if the low mood never lifted, which tends to surface values obscured by the absence of motivation. Use the answer to choose one small action, not a full life overhaul.', '[{"id": "f0", "type": "textarea", "label": "Even without motivation, what still feels like it matters to you?"}, {"id": "f1", "type": "textarea", "label": "What has low mood made harder to act on, even though it still matters?"}, {"id": "f2", "type": "textarea", "label": "What is one small action, values in hand, you could take today?"}, {"id": "f3", "type": "textarea", "label": "What got in the way the last time you tried something like this?"}]'::jsonb, array['depression', 'values', 'core ACT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('behavioral-activation-barrier-troubleshoot', 'Behavioral Activation Barrier Troubleshoot', 'dbt'::resource_kind, 'A troubleshooting sheet for identifying why a planned activity did not happen and adjusting the plan.', 'Use it to problem-solve stalled behavioral activation plans rather than abandoning them.', array['Adults', 'Teens']::text[], '15 minutes', 'When a planned activity does not happen, treat it as a troubleshooting problem rather than a personal failure. Common barriers include the task being too large, too vague, or scheduled at low-energy times; naming the specific barrier makes the next attempt more realistic. Shrink the task until it feels almost too easy before trying again.', '[{"id": "f0", "type": "textarea", "label": "What activity did you plan that did not happen?"}, {"id": "f1", "type": "textarea", "label": "What got in the way?"}, {"id": "f2", "type": "textarea", "label": "How could the task be made smaller or easier?"}, {"id": "f3", "type": "textarea", "label": "When will you try again, and what will be different?"}]'::jsonb, array['depression', 'behavioral activation', 'problem solving']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('supporting-a-partners-low-mood-without-rescuing', 'Supporting a Partner''s Low Mood Without Rescuing', 'couples'::resource_kind, 'A conversation guide for a partner to offer support without over-functioning or fixing.', 'Use it to help a supporting partner find a sustainable middle ground between helping and rescuing.', array['Couples']::text[], '25 minutes', 'Supporting partners often swing between overfunctioning, taking over everything, and burning out or resenting it. This conversation names specific tasks the depressed partner can still manage versus ones that genuinely need support, so help has boundaries. Check in on the supporting partner''s own needs too, since caregiver strain is common and worth naming.', '[{"id": "f0", "type": "textarea", "label": "Partner with low mood: what do you want help with right now?"}, {"id": "f1", "type": "textarea", "label": "What do you want to keep doing yourself, even if it is hard?"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: what is sustainable for you to offer right now?"}, {"id": "f3", "type": "textarea", "label": "What does the supporting partner need for themselves?"}]'::jsonb, array['depression', 'support', 'relationship issues']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('task-friction-audit-worksheet', 'Task Friction Audit Worksheet', 'worksheet'::resource_kind, 'A worksheet identifying the small frictions that make starting a task harder than it needs to be.', 'Use it to find and remove small obstacles that block task initiation.', array['Adults', 'Teens']::text[], '20 minutes', 'Friction is often small and fixable: a task requiring three steps before it can even start, a missing supply, an unclear first move. Walk through a stuck task in detail and look for the exact point it stalls rather than assuming the problem is motivation. Reducing friction by even one step often unsticks a task that willpower alone could not.', '[{"id": "f0", "type": "textarea", "label": "What task have you been avoiding starting?"}, {"id": "f1", "type": "textarea", "label": "What has to happen before you can even begin?"}, {"id": "f2", "type": "textarea", "label": "Where exactly does it usually stall?"}, {"id": "f3", "type": "textarea", "label": "What is one way to reduce the friction at that point?"}]'::jsonb, array['ADHD', 'task initiation', 'executive function']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('time-blindness-reality-check-log', 'Time Blindness Reality Check Log', 'cbt'::resource_kind, 'A log comparing estimated versus actual time spent on tasks to build a more accurate internal clock.', 'Use it to build more accurate time estimates by tracking the gap over time.', array['Adults', 'Teens']::text[], 'One week', 'Have the client estimate how long a task will take before starting, then log the actual time it took. The gap is usually informative rather than embarrassing, and naming it as a real perceptual difference, not laziness, tends to reduce shame. Use the pattern to build in buffer time for future planning.', '[{"id": "f0", "type": "textarea", "label": "What task are you about to start?"}, {"id": "f1", "type": "textarea", "label": "How long do you estimate it will take?"}, {"id": "f2", "type": "textarea", "label": "How long did it actually take?"}, {"id": "f3", "type": "textarea", "label": "What does the pattern across several tasks tell you?"}]'::jsonb, array['ADHD', 'self-monitoring', 'executive function']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('rejection-sensitivity-check-card', 'Rejection Sensitivity Check Card', 'dbt'::resource_kind, 'A short card for checking whether a perceived criticism is as big as it feels in the moment.', 'Use it to slow down and check facts before reacting to a felt slight.', array['Adults', 'Teens']::text[], 'Ten minutes', 'Many clients with ADHD describe a sharp, outsized sting from perceived criticism or rejection. This card is a quick facts-check to use in the moment: what exactly was said, how big does it feel, and what would checking the facts show. It will not remove the sting entirely, but it can slow the urge to react before checking.', '[{"id": "f0", "type": "textarea", "label": "What was said or happened that felt like a criticism or rejection?"}, {"id": "f1", "type": "textarea", "label": "How big does it feel right now, 0 to 10?"}, {"id": "f2", "type": "textarea", "label": "What do the actual facts of the situation suggest?"}, {"id": "f3", "type": "textarea", "label": "What is a response that fits the facts rather than the feeling?"}]'::jsonb, array['ADHD', 'check the facts']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('focus-fidget-toolkit-build', 'Focus Fidget Toolkit Build', 'kids'::resource_kind, 'A craft where a child builds a small kit of fidget and focus tools to keep at their desk.', 'Use it to give a child hands-on tools that support focus, chosen and built by them.', array['Children']::text[], '30 minutes', 'Let the child choose from a few simple options, a stress ball, a textured strip, a doodle pad, and build or decorate their own version rather than handing over a premade kit. A parent can help gather materials and keep the kit stocked at home or school. Frame fidgeting as something that can help focus, not something to be stopped.', '[{"id": "f0", "type": "textarea", "label": "Which fidget tools do you want to build or decorate?"}, {"id": "f1", "type": "textarea", "label": "Where will you keep your kit?"}, {"id": "f2", "type": "textarea", "label": "When during the day might you use it?"}, {"id": "f3", "type": "textarea", "label": "Parent: where else might a kit like this help, like homework time?"}]'::jsonb, array['ADHD', 'children']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('beat-the-distraction-relay-game', 'Beat the Distraction Relay Game', 'game'::resource_kind, 'A relay game practicing refocusing after a planted distraction interrupts a simple task.', 'Use it to practice noticing distraction and returning to task in a low-stakes, playful way.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Give players a simple repetitive task, like sorting cards, and plant a distraction partway through, a noise, a question, a funny prop. The goal is to notice the distraction and return to the task, timed for fun rather than judged. Debrief on what helped them return fastest, since that becomes a transferable skill.', '[{"id": "f0", "type": "textarea", "label": "What was the task you were sorting or building?"}, {"id": "f1", "type": "textarea", "label": "What was the distraction that popped up?"}, {"id": "f2", "type": "textarea", "label": "How quickly did you notice you had gotten distracted?"}, {"id": "f3", "type": "textarea", "label": "What helped you get back to the task?"}]'::jsonb, array['ADHD', 'attention', 'group']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('substance-use-function-map', 'Substance Use Function Map', 'worksheet'::resource_kind, 'A worksheet mapping what function substance use currently serves in a client''s life.', 'Use it to identify what need substance use is meeting so it can be met another way.', array['Adults', 'Teens']::text[], '25 minutes', 'Substance use nearly always serves a function, relief, connection, numbing, energy, even when it also causes harm. Naming the function honestly, without a client feeling judged for it, opens the door to finding another way to meet the same need. Keep language centered on substance use and urges, never on labeling the client.', '[{"id": "f0", "type": "textarea", "label": "What does substance use currently help you feel, avoid, or get through?"}, {"id": "f1", "type": "textarea", "label": "When is the urge to use strongest?"}, {"id": "f2", "type": "textarea", "label": "What need is being met in those moments?"}, {"id": "f3", "type": "textarea", "label": "What else, even partially, could meet that same need?"}]'::jsonb, array['addiction', 'substance use', 'formulation']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('urge-timeline-and-peak-tracker', 'Urge Timeline and Peak Tracker', 'cbt'::resource_kind, 'A tracker charting how an urge rises, peaks and fades over time on a given day.', 'Use it to build confidence that urges pass on their own within a limited window.', array['Adults', 'Teens']::text[], 'One week', 'Have the client rate the urge every ten to fifteen minutes once it starts, plotting a rough curve. Most urges peak and fall within twenty to forty-five minutes, and seeing that shape on paper builds real confidence that riding it out is possible. Compare several tracked urges to build a pattern the client can trust.', '[{"id": "f0", "type": "textarea", "label": "What time did the urge start, and what triggered it?"}, {"id": "f1", "type": "textarea", "label": "Rate the urge every ten to fifteen minutes, 0 to 10."}, {"id": "f2", "type": "textarea", "label": "What was the highest point it reached?"}, {"id": "f3", "type": "textarea", "label": "How long did it take to noticeably drop?"}]'::jsonb, array['addiction', 'substance use', 'urges', 'self-monitoring']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('values-and-sobriety-compass', 'Values and Sobriety Compass', 'act'::resource_kind, 'A worksheet connecting a client''s stated values to the daily choice around substance use.', 'Use it to link the choice to use or not use back to what a client cares about most.', array['Adults', 'Teens']::text[], '20 minutes', 'Rather than framing every choice around willpower, this worksheet connects the daily decision to a client''s own stated values, relationships, health, work, parenting, whatever matters most to them. The urge to use rarely disappears from values work alone, but it gives the client something to weigh the urge against. Revisit the compass often, since values can shift over the course of recovery.', '[{"id": "f0", "type": "textarea", "label": "What matters most to you right now, in this season of life?"}, {"id": "f1", "type": "textarea", "label": "How does substance use help or hurt that?"}, {"id": "f2", "type": "textarea", "label": "What would moving toward that value look like today?"}, {"id": "f3", "type": "textarea", "label": "What might get in the way, and how could you handle it?"}]'::jsonb, array['addiction', 'substance use', 'values']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('urge-riding-skills-card', 'Urge Riding Skills Card', 'dbt'::resource_kind, 'A reference card of distress tolerance skills matched to different intensities of urge.', 'Use it to match a specific skill to how strong an urge currently feels.', array['Adults', 'Teens']::text[], '15 minutes', 'Sort skills by intensity, a quick distraction for a mild urge, TIPP or intense sensation for a strong one, so a client is not left guessing what might help in the moment. Practice each skill in session before relying on the card during a real urge. Update the card together as the client learns what actually works for them.', '[{"id": "f0", "type": "textarea", "label": "What skill works for a mild urge, around 3 out of 10?"}, {"id": "f1", "type": "textarea", "label": "What skill works for a moderate urge, around 6 out of 10?"}, {"id": "f2", "type": "textarea", "label": "What skill works for an intense urge, 8 or higher?"}, {"id": "f3", "type": "textarea", "label": "Which skill have you actually used, and how did it go?"}]'::jsonb, array['addiction', 'substance use', 'urges', 'distress tolerance']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('support-without-monitoring-conversation', 'Support Without Monitoring Conversation', 'couples'::resource_kind, 'A conversation guide helping a couple find support that does not slide into surveillance.', 'Use it to help partners agree on support that feels helpful rather than policed.', array['Couples']::text[], '30 minutes', 'A partner supporting someone working on substance use often defaults to checking up, which can breed resentment on both sides even when it comes from care. This conversation names specific, agreed forms of support, checking in at certain times, being available for a call, versus monitoring that was never asked for. Revisit the agreement as trust rebuilds.', '[{"id": "f0", "type": "textarea", "label": "Partner in recovery: what kind of support actually helps you?"}, {"id": "f1", "type": "textarea", "label": "What starts to feel like monitoring instead of support?"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: what do you need to feel less anxious?"}, {"id": "f3", "type": "textarea", "label": "What specific agreement can you both commit to this week?"}]'::jsonb, array['addiction', 'substance use', 'support']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('anger-cost-ledger', 'Anger Cost Ledger', 'worksheet'::resource_kind, 'A worksheet tallying what recent angry reactions have cost against what staying calm might gain.', 'Use it to weigh the real costs of reactive anger against the benefits of a paused response.', array['Adults', 'Teens']::text[], '20 minutes', 'List a handful of recent angry reactions alongside their actual cost, a damaged relationship, lost time, regret, and set that against what a paused response might have gained. This is not about suppressing anger, which is a valid signal, but about the reaction that follows it. Clients often underestimate the cumulative cost until it is written down.', '[{"id": "f0", "type": "textarea", "label": "Describe a recent moment you reacted in anger."}, {"id": "f1", "type": "textarea", "label": "What did that reaction cost you or someone else?"}, {"id": "f2", "type": "textarea", "label": "What might a paused, chosen response have looked like?"}, {"id": "f3", "type": "textarea", "label": "What might that have gained instead?"}]'::jsonb, array['anger management', 'behavioral experiment']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('anger-trigger-thought-chain', 'Anger Trigger Thought Chain', 'cbt'::resource_kind, 'A chain worksheet tracing the thought that turns an irritation into full anger.', 'Use it to find the specific thought that escalates a minor irritation into anger.', array['Adults', 'Teens']::text[], '20 minutes', 'Anger usually has an appraisal underneath it, often about unfairness or disrespect, that turns an irritation into a full reaction. Trace the chain from trigger to thought to intensity, and look for the exact thought that does the escalating. Testing that specific thought, rather than the anger itself, is usually where change happens.', '[{"id": "f0", "type": "textarea", "label": "What was the triggering situation?"}, {"id": "f1", "type": "textarea", "label": "What thought went through your mind right after?"}, {"id": "f2", "type": "textarea", "label": "How did that thought change the intensity of your anger?"}, {"id": "f3", "type": "textarea", "label": "Is there another way to read the situation?"}]'::jsonb, array['anger management', 'automatic thoughts']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('anger-early-exit-plan', 'Anger Early Exit Plan', 'dbt'::resource_kind, 'A plan for exiting a heated moment early, before anger reaches a point of no return.', 'Use it to build a concrete, rehearsed plan for stepping away before anger peaks.', array['Adults', 'Teens']::text[], '15 minutes', 'The exit has to be planned and specific, a phrase to say, a place to go, a return time, or it tends to get skipped in the moment. Rehearse the exact wording out loud in session, since an awkward or vague exit line is one reason clients avoid using it. Agree with anyone affected, like a partner or family, that this plan exists ahead of time.', '[{"id": "f0", "type": "textarea", "label": "What is your early warning sign that anger is building?"}, {"id": "f1", "type": "textarea", "label": "What exact phrase will you use to exit the moment?"}, {"id": "f2", "type": "textarea", "label": "Where will you go, and for how long?"}, {"id": "f3", "type": "textarea", "label": "What will you do while you are away to cool down?"}]'::jsonb, array['anger management', 'distress tolerance']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('repair-after-an-angry-moment-conversation', 'Repair After an Angry Moment Conversation', 'couples'::resource_kind, 'A guided conversation for repairing with a partner after an angry outburst.', 'Use it to structure a genuine repair after anger has affected a partner.', array['Couples']::text[], '25 minutes', 'A repair needs to name the specific behavior, not just say sorry in general, and it needs to include what will be different next time. The partner on the receiving end also needs space to say what the moment was like for them without being rushed past. Avoid re-litigating who was right; that is a separate conversation from repair.', '[{"id": "f0", "type": "textarea", "label": "What specifically happened that you want to repair?"}, {"id": "f1", "type": "textarea", "label": "What was that like for your partner?"}, {"id": "f2", "type": "textarea", "label": "What will you do differently next time you feel that angry?"}, {"id": "f3", "type": "textarea", "label": "What does your partner need to feel repair has actually happened?"}]'::jsonb, array['anger management', 'repair']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('anger-volcano-craft', 'Anger Volcano Craft', 'kids'::resource_kind, 'A craft where a child builds a paper volcano showing the buildup from calm to eruption.', 'Use it to help a child see anger building in stages rather than arriving all at once.', array['Children']::text[], '30 minutes', 'Build the volcano in layers, from calm at the base to eruption at the top, and have the child mark body clues at each layer, like a hot face or tight fists. The goal is catching anger lower on the volcano, where it is easier to manage, rather than only after it erupts. A parent can help the child notice their own layers at home.', '[{"id": "f0", "type": "textarea", "label": "Color the bottom of the volcano: what does calm feel like in your body?"}, {"id": "f1", "type": "textarea", "label": "Color the middle: what does your body feel like when anger is building?"}, {"id": "f2", "type": "textarea", "label": "Color the top: what happens when anger erupts?"}, {"id": "f3", "type": "textarea", "label": "What could help you at the middle layer, before the top?"}]'::jsonb, array['anger management', 'children']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('compulsion-cost-benefit-ledger', 'Compulsion Cost-Benefit Ledger', 'worksheet'::resource_kind, 'A worksheet weighing the short-term relief of a compulsion against its longer-term cost.', 'Use it to make the trade-off of a compulsion visible over both short and long timeframes.', array['Adults', 'Teens']::text[], '20 minutes', 'Compulsions offer real short-term relief, which is exactly why they persist; naming that honestly, rather than dismissing it, builds trust. Then widen the timeframe to the longer-term cost, time lost, life narrowed, relief that never lasts. Seeing both columns side by side tends to shift motivation more than being told the compulsion is unhelpful.', '[{"id": "f0", "type": "textarea", "label": "Name one compulsion you do regularly."}, {"id": "f1", "type": "textarea", "label": "What relief does it give you in the short term?"}, {"id": "f2", "type": "textarea", "label": "What has it cost you over weeks or months?"}, {"id": "f3", "type": "textarea", "label": "Looking at both, what do you notice?"}]'::jsonb, array['OCD', 'behavioral experiment']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('intrusive-thought-ownership-check', 'Intrusive Thought Ownership Check', 'cbt'::resource_kind, 'A worksheet separating the content of an intrusive thought from what it says about the client.', 'Use it to challenge the belief that having a thought means something about the client''s character.', array['Adults', 'Teens']::text[], '20 minutes', 'A core piece of OCD work is separating a thought''s content from its meaning: having an intrusive thought does not mean a client wants it, endorses it, or is likely to act on it. Walk through the evidence for and against the thought meaning something about their character, and note how everyone has unwanted thoughts pass through their mind.', '[{"id": "f0", "type": "textarea", "label": "What intrusive thought has been bothering you?"}, {"id": "f1", "type": "textarea", "label": "What does it seem to say about you, at first glance?"}, {"id": "f2", "type": "textarea", "label": "What evidence actually supports that conclusion?"}, {"id": "f3", "type": "textarea", "label": "What is a more accurate way to understand having this thought?"}]'::jsonb, array['OCD', 'intrusive thoughts', 'core CBT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('certainty-chasing-defusion-practice', 'Certainty Chasing Defusion Practice', 'act'::resource_kind, 'A defusion exercise for noticing the mind''s demand for certainty before it can rest.', 'Use it to build a different relationship with the mind''s demand for full certainty.', array['Adults', 'Teens']::text[], '15 minutes', 'Name the pattern out loud: the mind insists on total certainty before it will allow relief, and OCD is expert at manufacturing doubt no amount of checking can fully satisfy. Practice noticing the demand for certainty as just another thought passing through, rather than a rule to obey. This pairs well with any existing uncertainty tolerance work.', '[{"id": "f0", "type": "textarea", "label": "What does your mind demand certainty about most often?"}, {"id": "f1", "type": "textarea", "label": "What has trying to reach full certainty actually gotten you?"}, {"id": "f2", "type": "textarea", "label": "Practice naming the thought: \"My mind is demanding certainty again.\" What shifts?"}, {"id": "f3", "type": "textarea", "label": "What could you do instead of chasing certainty, right now?"}]'::jsonb, array['OCD', 'defusion', 'uncertainty']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('ritual-postponement-ladder', 'Ritual Postponement Ladder', 'dbt'::resource_kind, 'A stepped plan for gradually increasing how long a compulsion is postponed before it can happen.', 'Use it to build tolerance for delay through a graduated, planned sequence.', array['Adults', 'Teens']::text[], 'One to two weeks', 'Start with a delay short enough to actually succeed at, even five minutes, and build the interval up gradually rather than jumping to full resistance. Pair the wait with a distress tolerance skill from the client''s existing toolkit. Track each attempt so progress across the ladder is visible over time.', '[{"id": "f0", "type": "textarea", "label": "Which compulsion are you working on postponing?"}, {"id": "f1", "type": "textarea", "label": "What is your current, doable delay time?"}, {"id": "f2", "type": "textarea", "label": "What skill will you use while you wait?"}, {"id": "f3", "type": "textarea", "label": "How did the wait go? Are you ready to increase the delay?"}]'::jsonb, array['OCD', 'distress tolerance']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('worry-bug-feeding-chart', 'Worry Bug Feeding Chart', 'kids'::resource_kind, 'A chart where a child tracks times they did not feed their "worry bug" with a ritual.', 'Use it to give a child a visual, encouraging tally of resisting a ritual.', array['Children']::text[], 'One week', 'Pair this with an externalizing name the child already uses for their OCD, like a worry bug or bossy brain. Each time the child notices an urge and does not feed it, they add a mark or sticker, building a visible record of successes rather than dwelling on the times it did not work. Celebrate small counts; this is genuinely hard for a child to do.', '[{"id": "f0", "type": "textarea", "label": "Draw or name your worry bug."}, {"id": "f1", "type": "textarea", "label": "Each day, mark how many times you did not feed it."}, {"id": "f2", "type": "textarea", "label": "What helped you not feed it?"}, {"id": "f3", "type": "textarea", "label": "What do you want to tell your worry bug at the end of the week?"}]'::jsonb, array['OCD', 'children', 'externalizing']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('panic-onset-pattern-worksheet', 'Panic Onset Pattern Worksheet', 'worksheet'::resource_kind, 'A worksheet mapping the time, place and situation around recent panic attacks to find patterns.', 'Use it to identify situational patterns that precede a client''s panic attacks.', array['Adults', 'Teens']::text[], '20 minutes', 'Log the last several panic attacks with time, place, and what was happening just before, looking for a shared thread, a physical sensation, a place, a type of situation. Some clients find no clear pattern, which is itself useful information about how unpredictable panic can feel. Use whatever pattern emerges to plan targeted practice.', '[{"id": "f0", "type": "textarea", "label": "When and where did your last panic attack happen?"}, {"id": "f1", "type": "textarea", "label": "What was happening right before it started?"}, {"id": "f2", "type": "textarea", "label": "Looking at several attacks, is there a shared pattern?"}, {"id": "f3", "type": "textarea", "label": "What would you want to practice based on that pattern?"}]'::jsonb, array['panic attacks', 'self-monitoring', 'triggers']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('panic-sensation-misinterpretation-log', 'Panic Sensation Misinterpretation Log', 'cbt'::resource_kind, 'A log comparing the feared meaning of a body sensation with its actual, harmless explanation.', 'Use it to challenge catastrophic interpretations of normal panic sensations.', array['Adults', 'Teens']::text[], '20 minutes', 'Panic often runs on a sensation being misread as dangerous, a racing heart read as a heart attack, dizziness read as fainting or worse. List the sensation, the feared interpretation, and a more accurate, harmless explanation grounded in what is known about the body''s alarm response. Complete this in session rather than assigning it as homework during an actual panic episode.', '[{"id": "f0", "type": "textarea", "label": "What body sensation shows up during panic?"}, {"id": "f1", "type": "textarea", "label": "What do you fear it means in that moment?"}, {"id": "f2", "type": "textarea", "label": "What is a more accurate explanation for that sensation?"}, {"id": "f3", "type": "textarea", "label": "How does the accurate explanation change how you respond?"}]'::jsonb, array['panic attacks', 'core CBT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('willing-to-feel-the-wave-practice', 'Willing to Feel the Wave Practice', 'act'::resource_kind, 'A willingness exercise practicing making room for panic sensations rather than fighting them.', 'Use it to build willingness to let a panic sensation be present without struggling against it.', array['Adults', 'Teens']::text[], '15 minutes', 'The struggle against a panic sensation often intensifies it more than the sensation itself; this exercise practices making room instead. Guide the client to notice the sensation''s exact location and shape, then breathe around it rather than trying to push it away. This is a willingness practice for session use, not a stand-alone crisis skill.', '[{"id": "f0", "type": "textarea", "label": "Where in your body does panic usually show up first?"}, {"id": "f1", "type": "textarea", "label": "Without trying to change it, what shape or size does it have?"}, {"id": "f2", "type": "textarea", "label": "Practice breathing around it rather than fighting it. What happened?"}, {"id": "f3", "type": "textarea", "label": "What is different about making room for it versus fighting it?"}]'::jsonb, array['panic attacks', 'willingness', 'core ACT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('supporting-someone-through-panic-conversation', 'Supporting Someone Through Panic Conversation', 'couples'::resource_kind, 'A conversation guide for a partner to learn what actually helps during the other''s panic attacks.', 'Use it to replace a partner''s guesswork with what the client has found actually helps.', array['Couples']::text[], '20 minutes', 'Partners often default to over-asking questions or urging someone to calm down, both of which can make panic worse. This conversation has the client name specifically what helps and what does not, so the supporting partner has clear, tested guidance instead of guesswork. Revisit it, since what helps can change over time.', '[{"id": "f0", "type": "textarea", "label": "What has actually helped you during a past panic attack?"}, {"id": "f1", "type": "textarea", "label": "What has made it worse, even if well intended?"}, {"id": "f2", "type": "textarea", "label": "Partner: what is one thing you can do next time, based on this?"}, {"id": "f3", "type": "textarea", "label": "What should the partner avoid doing?"}]'::jsonb, array['panic attacks', 'support']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('panic-facts-quick-fire-trivia-game', 'Panic Facts Quick-Fire Trivia Game', 'game'::resource_kind, 'A quick trivia game testing accurate facts about what panic attacks are and are not.', 'Use it to reinforce accurate, calming facts about panic in a playful, low-stakes format.', array['Teens', 'Adults', 'Groups']::text[], '15 minutes', 'Write a set of true-or-false statements about panic, such as whether it can cause fainting or lasts forever, and have players answer quickly before revealing the accurate answer. This reinforces psychoeducation in a lighter format than a straight lecture, which some clients absorb better. Follow any surprising answer with a short explanation.', '[{"id": "f0", "type": "textarea", "label": "True or false: panic attacks can cause a heart attack."}, {"id": "f1", "type": "textarea", "label": "True or false: panic attacks typically peak and pass within minutes."}, {"id": "f2", "type": "textarea", "label": "True or false: avoiding a place forever makes panic less likely there."}, {"id": "f3", "type": "textarea", "label": "Which answer surprised you most?"}]'::jsonb, array['panic attacks', 'psychoeducation']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('parent-self-care-minimum-worksheet', 'Parent Self-Care Minimum Worksheet', 'worksheet'::resource_kind, 'A worksheet identifying the smallest realistic version of self-care a stretched parent can sustain.', 'Use it to set a genuinely sustainable floor for a parent''s own basic needs.', array['Adults']::text[], '15 minutes', 'Ambitious self-care plans tend to fail for parents with little spare time; this worksheet aims lower on purpose, at the smallest version that could actually happen most days. Ask what has been dropped entirely and which of those matters most to restore first. A five-minute version of something is far better than an abandoned hour-long version.', '[{"id": "f0", "type": "textarea", "label": "What self-care have you dropped since becoming, or while being, a parent?"}, {"id": "f1", "type": "textarea", "label": "Which one matters most to restore?"}, {"id": "f2", "type": "textarea", "label": "What is the smallest version of it that could fit into most days?"}, {"id": "f3", "type": "textarea", "label": "What would need to be true for that to actually happen?"}]'::jsonb, array['parenting', 'self-monitoring']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('parent-guilt-thought-challenge', 'Parent Guilt Thought Challenge', 'cbt'::resource_kind, 'A worksheet examining a guilty parenting thought against the evidence of what actually happened.', 'Use it to test whether a guilty parenting thought fits the actual facts.', array['Adults']::text[], '20 minutes', 'Parenting guilt often runs on an all-or-nothing standard, one hard moment taken as proof of being a bad parent overall. Walk through the specific evidence for and against that conclusion, including what the parent did well in the same stretch of time. This is not about excusing harmful behavior, only about testing an unfairly harsh verdict.', '[{"id": "f0", "type": "textarea", "label": "What guilty thought have you had about your parenting recently?"}, {"id": "f1", "type": "textarea", "label": "What evidence supports that thought?"}, {"id": "f2", "type": "textarea", "label": "What evidence goes against it?"}, {"id": "f3", "type": "textarea", "label": "What is a fairer way to think about the situation?"}]'::jsonb, array['parenting', 'core CBT', 'self-criticism']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('parenting-values-in-hard-moments-practice', 'Parenting Values in Hard Moments Practice', 'act'::resource_kind, 'An exercise connecting a parent''s stated values to how they want to respond in a hard moment.', 'Use it to plan a values-guided response before the next hard parenting moment arrives.', array['Adults']::text[], '20 minutes', 'Ask what kind of parent the client wants to be in the moments that are hardest, not the easy ones, since values show up most clearly under pressure. Compare that to how a recent hard moment actually went, without judgment, then plan one small shift for next time. This works well alongside any parenting skills training already underway.', '[{"id": "f0", "type": "textarea", "label": "What kind of parent do you want to be in a hard moment?"}, {"id": "f1", "type": "textarea", "label": "Describe a recent hard moment. How did it actually go?"}, {"id": "f2", "type": "textarea", "label": "What is the gap between the two?"}, {"id": "f3", "type": "textarea", "label": "What is one small shift you could try next time?"}]'::jsonb, array['parenting', 'values', 'core ACT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('family-job-chart-craft', 'Family Job Chart Craft', 'kids'::resource_kind, 'A craft where a child helps design a chore chart with age-appropriate family jobs.', 'Use it to give a child ownership over their contribution to the household.', array['Children']::text[], '30 minutes', 'Let the child choose from a short list of age-appropriate jobs and decorate the chart themselves, which builds buy-in beyond a chart the parent simply assigns. Keep expectations realistic for the child''s age, and pair the chart with parent follow-through and specific praise rather than only consequences. Review and adjust it together every few weeks.', '[{"id": "f0", "type": "textarea", "label": "Which family jobs do you want to be in charge of?"}, {"id": "f1", "type": "textarea", "label": "How will you know when a job is done well?"}, {"id": "f2", "type": "textarea", "label": "Decorate your chart."}, {"id": "f3", "type": "textarea", "label": "Parent: how will you notice and praise these jobs getting done?"}]'::jsonb, array['parenting', 'children']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('family-feud-fair-rules-game', 'Family Feud Fair Rules Game', 'game'::resource_kind, 'A family game where the group votes on fair house rules for common daily flashpoints.', 'Use it to build buy-in for house rules by involving the whole family in setting them.', array['Adults', 'Children', 'Groups']::text[], '30 minutes', 'Present a common flashpoint, like screen time or bedtime, and have each family member propose a rule before the group votes on a version everyone can live with. Kids tend to follow rules they helped shape far more than ones handed down. Keep the tone playful, like a game show, to lower defensiveness on all sides.', '[{"id": "f0", "type": "textarea", "label": "What is a household situation that often causes conflict?"}, {"id": "f1", "type": "textarea", "label": "Each person proposes a rule for it."}, {"id": "f2", "type": "textarea", "label": "Vote on a version everyone can accept."}, {"id": "f3", "type": "textarea", "label": "How will the family check in on whether it is working?"}]'::jsonb, array['parenting', 'family']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('postpartum-identity-shift-worksheet', 'Postpartum Identity Shift Worksheet', 'worksheet'::resource_kind, 'A worksheet exploring what has changed and what remains in a new parent''s sense of self.', 'Use it to name the identity shift of new parenthood without treating it as pure loss.', array['Adults']::text[], '20 minutes', 'New parenthood reshapes identity fast, and clients can feel disoriented without language for what has changed. Ask what has been set aside, what remains, and what is genuinely new and wanted, holding space for grief and gain existing side by side. Avoid rushing to reassurance before the client has had room to name the shift honestly.', '[{"id": "f0", "type": "textarea", "label": "What part of yourself feels set aside right now?"}, {"id": "f1", "type": "textarea", "label": "What part of yourself still feels present?"}, {"id": "f2", "type": "textarea", "label": "What is new about who you are that you did not expect?"}, {"id": "f3", "type": "textarea", "label": "What would help you feel more like yourself again, even briefly?"}]'::jsonb, array['perinatal and postpartum', 'formulation']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('postpartum-expectation-vs-reality-log', 'Postpartum Expectation vs Reality Log', 'cbt'::resource_kind, 'A log comparing what a new parent expected postpartum life to look like against how it actually looks.', 'Use it to close the gap between an idealized expectation and lived reality without judgment.', array['Adults']::text[], '20 minutes', 'Many new parents carry an unspoken expectation, often shaped by others'' curated stories, that sets up a painful comparison to their own harder reality. Write both columns honestly, then ask where the expectation came from and whether it was ever realistic. This is not about lowering hope, only about correcting an unfair standard.', '[{"id": "f0", "type": "textarea", "label": "What did you expect postpartum life would be like?"}, {"id": "f1", "type": "textarea", "label": "What has it actually been like?"}, {"id": "f2", "type": "textarea", "label": "Where did that expectation come from?"}, {"id": "f3", "type": "textarea", "label": "How would a more realistic expectation change how you judge yourself?"}]'::jsonb, array['perinatal and postpartum', 'core CBT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('present-moment-with-baby-practice', 'Present Moment With Baby Practice', 'act'::resource_kind, 'A brief present-moment exercise for connecting with a baby amid exhaustion and racing thoughts.', 'Use it to practice brief moments of present-moment contact with a baby despite fatigue.', array['Adults']::text[], 'Five minutes', 'Exhaustion and intrusive worry can pull a new parent''s attention away from the baby in front of them even during quiet moments. Guide a short practice noticing the baby''s weight, sound, or smell without needing to feel a particular way about it. This is about brief contact, not manufacturing feelings that are not there yet.', '[{"id": "f0", "type": "textarea", "label": "Notice the weight or warmth of your baby right now, or imagine a recent moment."}, {"id": "f1", "type": "textarea", "label": "Notice one sound your baby makes."}, {"id": "f2", "type": "textarea", "label": "What thoughts pulled your attention away?"}, {"id": "f3", "type": "textarea", "label": "What was it like to come back to the present moment, even briefly?"}]'::jsonb, array['perinatal and postpartum', 'present moment']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('postpartum-support-request-script', 'Postpartum Support Request Script', 'couples'::resource_kind, 'A script for a new parent to ask directly for specific help rather than hoping a partner notices.', 'Use it to replace vague hoping for help with a direct, specific request.', array['Couples']::text[], '20 minutes', 'New parents often wait to be noticed rather than asking directly, then feel resentful when help does not arrive. Coach a specific, concrete request, what, when, and how, rather than a general complaint about being tired. The supporting partner practices responding to the specific ask rather than a vague sense that something is wrong.', '[{"id": "f0", "type": "textarea", "label": "What specific task do you need help with this week?"}, {"id": "f1", "type": "textarea", "label": "When would that help make the biggest difference?"}, {"id": "f2", "type": "textarea", "label": "Practice asking directly, in one or two sentences."}, {"id": "f3", "type": "textarea", "label": "Partner: what is your response to that specific request?"}]'::jsonb, array['perinatal and postpartum', 'communication']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('welcoming-the-baby-family-craft', 'Welcoming the Baby Family Craft', 'kids'::resource_kind, 'A craft for an older sibling to make a welcome item for a new baby, easing the transition.', 'Use it to give an older sibling a positive, active role in welcoming a new baby.', array['Children']::text[], '30 minutes', 'An older sibling adjusting to a new baby often needs a concrete way to feel included rather than displaced. Have them make something for the baby, a drawing, a small toy, or a card, and talk through what their new "big sibling" job will be. Parents can use this as an opening to name and validate any mixed feelings the sibling has too.', '[{"id": "f0", "type": "textarea", "label": "What will you make or draw to welcome the new baby?"}, {"id": "f1", "type": "textarea", "label": "What is one job you want to have as a big sibling?"}, {"id": "f2", "type": "textarea", "label": "What feels exciting about being a big sibling?"}, {"id": "f3", "type": "textarea", "label": "What feels hard or confusing about it?"}]'::jsonb, array['perinatal and postpartum', 'children']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('personal-standards-fairness-audit', 'Personal Standards Fairness Audit', 'worksheet'::resource_kind, 'A worksheet comparing the standard a client holds themselves to against one they would offer a friend.', 'Use it to notice a double standard between self-judgment and how a client treats others.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients with low self-esteem often hold a much harsher standard for themselves than for anyone else. List a recent self-critical moment, then ask what standard was actually applied, and whether that same standard would be applied to a friend in the same spot. The gap, once visible, is often the most persuasive part of the exercise.', '[{"id": "f0", "type": "textarea", "label": "Describe a recent moment you judged yourself harshly."}, {"id": "f1", "type": "textarea", "label": "What standard were you holding yourself to?"}, {"id": "f2", "type": "textarea", "label": "Would you hold a friend to that same standard? Why or why not?"}, {"id": "f3", "type": "textarea", "label": "What is a fairer standard for yourself?"}]'::jsonb, array['self-esteem', 'self-criticism']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('evidence-against-the-inner-critic-worksheet', 'Evidence Against the Inner Critic Worksheet', 'cbt'::resource_kind, 'A worksheet gathering specific counter-evidence against a client''s harshest self-belief.', 'Use it to build a concrete evidence file against an entrenched negative self-belief.', array['Adults', 'Teens']::text[], '20 minutes', 'Name the core negative belief plainly, then spend the bulk of the time gathering specific, concrete counter-evidence rather than generic positive statements. Weak, vague evidence rarely dents a strongly held belief, so push for detail and dates where possible. Keep the finished list somewhere the client can add to it over time.', '[{"id": "f0", "type": "textarea", "label": "What is the harshest belief you hold about yourself?"}, {"id": "f1", "type": "textarea", "label": "List three specific moments that contradict that belief, with detail."}, {"id": "f2", "type": "textarea", "label": "What would someone who knows you well say about that belief?"}, {"id": "f3", "type": "textarea", "label": "How strongly do you believe it now, 0 to 100, compared to before?"}]'::jsonb, array['self-esteem', 'core beliefs', 'evidence log']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('self-as-more-than-one-story-practice', 'Self as More Than One Story Practice', 'act'::resource_kind, 'An exercise widening a client''s self-story beyond one dominant negative narrative.', 'Use it to notice that a client is more than any single story they tell about themselves.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients with low self-esteem often carry one dominant story, like "I am not good enough," that crowds out every other truth about them. Have the client name that story, then list other true stories that also exist alongside it, without needing to erase the first one. The goal is not replacing the story but holding it alongside others.', '[{"id": "f0", "type": "textarea", "label": "What is the dominant story you tell about yourself?"}, {"id": "f1", "type": "textarea", "label": "What is another true story about you that also exists?"}, {"id": "f2", "type": "textarea", "label": "And another?"}, {"id": "f3", "type": "textarea", "label": "What is it like to hold more than one story at once?"}]'::jsonb, array['self-esteem', 'self-as-context', 'core ACT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('proud-moments-jar-craft', 'Proud Moments Jar Craft', 'kids'::resource_kind, 'A craft where a child decorates a jar and fills it over time with small proud moments.', 'Use it to build a visible, growing collection of a child''s own proud moments.', array['Children']::text[], '20 minutes, ongoing', 'Decorate the jar together in the first session, then send it home with a stack of small paper slips for the child to add to whenever something makes them proud, big or small. A parent can prompt gently at day''s end if the child forgets. Bring the jar back in future sessions to read a few slips together.', '[{"id": "f0", "type": "textarea", "label": "Decorate your jar."}, {"id": "f1", "type": "textarea", "label": "Write or draw one thing you are proud of right now to start it off."}, {"id": "f2", "type": "textarea", "label": "Parent: how will you remind your child to add to the jar?"}, {"id": "f3", "type": "textarea", "label": "What do you hope the jar looks like in a month?"}]'::jsonb, array['self-esteem', 'children']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('strength-charades-game', 'Strength Charades Game', 'game'::resource_kind, 'A charades game where players act out a personal strength for others to guess.', 'Use it to make naming personal strengths active and fun rather than a quiet list.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Write a list of strengths, kind, brave, funny, patient, on cards, and have players act one out without words for the group to guess. Afterward, ask each player to name a time they showed that strength themselves. This works well in groups where members may be reluctant to name their own strengths unprompted.', '[{"id": "f0", "type": "textarea", "label": "Pick a strength card and act it out."}, {"id": "f1", "type": "textarea", "label": "What strength did you guess for others?"}, {"id": "f2", "type": "textarea", "label": "Name a time you showed one of these strengths yourself."}, {"id": "f3", "type": "textarea", "label": "Which strength would you like to use more often?"}]'::jsonb, array['self-esteem', 'strengths', 'group']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('post-social-review-bias-check', 'Post-Social Review Bias Check', 'worksheet'::resource_kind, 'A worksheet comparing a client''s harsh post-event self-review against what an observer likely saw.', 'Use it to correct an overly harsh internal replay of a social interaction.', array['Adults', 'Teens']::text[], '20 minutes', 'After a social event, clients with social anxiety often replay a self-critical highlight reel that does not match how an outside observer likely experienced the same moment. Write both versions side by side, and if possible, ask a trusted person for their honest recollection to compare. The gap between the two versions is usually the point that lands.', '[{"id": "f0", "type": "textarea", "label": "Describe a recent social moment you have been replaying critically."}, {"id": "f1", "type": "textarea", "label": "What is your harshest version of what happened?"}, {"id": "f2", "type": "textarea", "label": "What would a neutral observer likely have noticed instead?"}, {"id": "f3", "type": "textarea", "label": "What does comparing the two tell you?"}]'::jsonb, array['social anxiety', 'core CBT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('safety-behavior-identification-worksheet', 'Safety Behavior Identification Worksheet', 'cbt'::resource_kind, 'A worksheet identifying the small safety behaviors a client uses to get through social situations.', 'Use it to surface hidden safety behaviors that quietly maintain social anxiety.', array['Adults', 'Teens']::text[], '20 minutes', 'Safety behaviors are often subtle, rehearsing lines in advance, avoiding eye contact, standing near an exit, and clients rarely notice them as a category until asked directly. List several, then rate how much each one seems to help versus how much it might be preventing the client from learning the feared outcome will not happen. This sets up later work on dropping them one at a time.', '[{"id": "f0", "type": "textarea", "label": "What small things do you do to get through social situations more easily?"}, {"id": "f1", "type": "textarea", "label": "How much does each one seem to help, 0 to 10?"}, {"id": "f2", "type": "textarea", "label": "What might each one be preventing you from learning?"}, {"id": "f3", "type": "textarea", "label": "Which one would you consider dropping first?"}]'::jsonb, array['social anxiety', 'safety behaviors']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('willing-to-be-seen-practice', 'Willing to Be Seen Practice', 'act'::resource_kind, 'A willingness exercise practicing being visible in a small social moment without hiding.', 'Use it to build willingness to be seen, awkwardness included, in a small social moment.', array['Adults', 'Teens']::text[], '15 minutes', 'Pick a small, low-stakes moment of being seen, speaking up once in a group, holding eye contact briefly, and have the client practice it while making room for the discomfort rather than trying to eliminate it first. The point is not comfort but willingness. Debrief on what it was like to act despite the discomfort, not whether the discomfort went away.', '[{"id": "f0", "type": "textarea", "label": "What small moment of being seen will you practice?"}, {"id": "f1", "type": "textarea", "label": "What discomfort do you expect to show up?"}, {"id": "f2", "type": "textarea", "label": "Practice it while making room for that discomfort. What happened?"}, {"id": "f3", "type": "textarea", "label": "What did you learn about acting despite discomfort?"}]'::jsonb, array['social anxiety', 'willingness', 'core ACT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('social-effort-pacing-card', 'Social Effort Pacing Card', 'dbt'::resource_kind, 'A card for pacing social exposure practice so it builds skill without overwhelming the client.', 'Use it to balance stretching a client''s social comfort zone against burning out on effort.', array['Adults', 'Teens']::text[], '15 minutes', 'Too much social exposure practice too fast can lead a client to quit altogether; this card helps calibrate a sustainable pace. Rate the planned social effort for the week, then check in on energy and willingness afterward before planning the next one. Some weeks call for pulling back, not just pushing forward.', '[{"id": "f0", "type": "textarea", "label": "What social effort are you planning this week?"}, {"id": "f1", "type": "textarea", "label": "How much energy do you expect it to take, 0 to 10?"}, {"id": "f2", "type": "textarea", "label": "After trying it, how did your energy and willingness hold up?"}, {"id": "f3", "type": "textarea", "label": "Should next week be a stretch, a repeat, or a step back?"}]'::jsonb, array['social anxiety', 'pacing']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('two-minute-conversation-challenge-game', 'Two-Minute Conversation Challenge Game', 'game'::resource_kind, 'A timed practice game for holding a light two-minute conversation on a randomly drawn topic.', 'Use it to build low-stakes practice holding a short conversation to completion.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Draw a light topic card, like a favorite show or a recent weekend, and set a timer for two minutes of conversation, in-session with the clinician or between group members. The short time limit lowers the stakes, since a conversation only has to last two minutes rather than feel indefinite. Debrief on what felt easier or harder than expected.', '[{"id": "f0", "type": "textarea", "label": "Draw a topic card and set a two-minute timer."}, {"id": "f1", "type": "textarea", "label": "How did the conversation feel while it was happening?"}, {"id": "f2", "type": "textarea", "label": "What was easier than you expected?"}, {"id": "f3", "type": "textarea", "label": "What would you want to practice next?"}]'::jsonb, array['social anxiety', 'exposure', 'group']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('grief-bursts-mapping-worksheet', 'Grief Bursts Mapping Worksheet', 'worksheet'::resource_kind, 'A worksheet mapping when and where unexpected waves of grief tend to show up.', 'Use it to help a client anticipate and plan for sudden grief bursts rather than being blindsided.', array['Adults', 'Teens']::text[], '20 minutes', 'Grief often arrives in short, intense bursts triggered by ordinary things, a song, a smell, a date, rather than as a steady state. Map recent bursts by trigger and setting to look for a pattern, and identify one or two upcoming situations likely to bring one on. Planning does not prevent the burst, but it makes it feel less like an ambush.', '[{"id": "f0", "type": "textarea", "label": "Describe a recent moment grief hit unexpectedly."}, {"id": "f1", "type": "textarea", "label": "What triggered it?"}, {"id": "f2", "type": "textarea", "label": "Is there a pattern across recent bursts?"}, {"id": "f3", "type": "textarea", "label": "What upcoming situation might bring one on, and how could you prepare?"}]'::jsonb, array['grief and loss', 'triggers']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('if-only-thought-fairness-check', 'If-Only Thought Fairness Check', 'cbt'::resource_kind, 'A worksheet testing a guilt-driven "if only" thought against what the client actually knew at the time.', 'Use it to test a hindsight-driven guilty thought against realistic knowledge at the time.', array['Adults', 'Teens']::text[], '20 minutes', 'If-only thoughts judge past decisions using information only available in hindsight, which is not a fair standard. Write the thought, then ask what the client actually knew and could have reasonably predicted at that exact moment, not what is obvious now. This does not erase grief, but it can loosen guilt that is not warranted by the facts.', '[{"id": "f0", "type": "textarea", "label": "What \"if only\" thought keeps coming up?"}, {"id": "f1", "type": "textarea", "label": "What did you actually know at that time, before it happened?"}, {"id": "f2", "type": "textarea", "label": "Could you have reasonably predicted the outcome with that information?"}, {"id": "f3", "type": "textarea", "label": "What is a fairer way to look at the decision you made?"}]'::jsonb, array['grief and loss', 'guilt', 'core CBT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('carrying-grief-and-living-practice', 'Carrying Grief and Living Practice', 'act'::resource_kind, 'An exercise exploring how to carry grief alongside continuing to live and engage with values.', 'Use it to explore carrying grief and moving toward values as compatible, not opposed.', array['Adults', 'Teens']::text[], '20 minutes', 'Some clients feel that moving forward means betraying the person or life they lost, which can keep them stuck between grieving and living. Frame carrying grief and continuing to act on values as two things that can coexist rather than compete. Ask what the person they lost might want for them, if that framing feels right to the client.', '[{"id": "f0", "type": "textarea", "label": "What does moving forward feel like it would mean or betray?"}, {"id": "f1", "type": "textarea", "label": "What value do you want to keep living out, even while grieving?"}, {"id": "f2", "type": "textarea", "label": "What would carrying both grief and this value look like, together?"}, {"id": "f3", "type": "textarea", "label": "What is one small step in that direction?"}]'::jsonb, array['grief and loss', 'values', 'acceptance']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('grieving-differently-as-a-couple-conversation', 'Grieving Differently as a Couple Conversation', 'couples'::resource_kind, 'A conversation guide for partners grieving the same loss in visibly different ways.', 'Use it to help partners understand and accept each other''s different grieving style.', array['Couples']::text[], '30 minutes', 'Partners often grieve the same loss differently, one more outwardly emotional, one more private or task-focused, and can misread each other''s style as not caring. Have each partner describe their own style and what they need, then reflect back what they heard before responding. Naming the difference as different, not wrong, tends to ease tension.', '[{"id": "f0", "type": "textarea", "label": "How does grief tend to show up for you?"}, {"id": "f1", "type": "textarea", "label": "What do you need from your partner right now?"}, {"id": "f2", "type": "textarea", "label": "Partner: what did you hear, and how did that surprise you, if at all?"}, {"id": "f3", "type": "textarea", "label": "What would it look like to respect each other''s different style?"}]'::jsonb, array['grief and loss', 'relationship issues']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('special-memory-keepsake-box-craft', 'Special Memory Keepsake Box Craft', 'kids'::resource_kind, 'A craft where a child decorates a small box to hold objects and drawings connected to someone they lost.', 'Use it to give a child a concrete, ongoing way to hold onto memories of someone they lost.', array['Children']::text[], '30 minutes', 'Let the child decorate the box however they like, then help them choose or draw a few small items connected to the person they lost, a photo, a drawing, a small object. This gives a concrete place for memories rather than asking a child to hold grief only in words. A parent can help add to the box over time as the child wants.', '[{"id": "f0", "type": "textarea", "label": "Decorate your memory box."}, {"id": "f1", "type": "textarea", "label": "What will you put inside it to start?"}, {"id": "f2", "type": "textarea", "label": "What is one memory you want to remember about this person?"}, {"id": "f3", "type": "textarea", "label": "Where will you keep your box at home?"}]'::jsonb, array['grief and loss', 'children']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('relationship-deal-breakers-and-preferences-sheet', 'Relationship Deal-Breakers and Preferences Sheet', 'worksheet'::resource_kind, 'A worksheet sorting relationship concerns into genuine deal-breakers versus flexible preferences.', 'Use it to clarify which relationship concerns are firm limits versus areas open to compromise.', array['Adults']::text[], '20 minutes', 'Clients sometimes treat every friction point in a relationship as equally serious, which makes every disagreement feel high-stakes. Sort a list of current concerns into genuine deal-breakers and preferences that could flex with negotiation. This distinction alone often lowers the temperature of ongoing conflict.', '[{"id": "f0", "type": "textarea", "label": "List your current concerns in the relationship."}, {"id": "f1", "type": "textarea", "label": "Which of these are true deal-breakers for you?"}, {"id": "f2", "type": "textarea", "label": "Which are preferences you could negotiate on?"}, {"id": "f3", "type": "textarea", "label": "What does that sorting change about how you want to approach them?"}]'::jsonb, array['relationship issues', 'decisions']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('relationship-story-rewrite-worksheet', 'Relationship Story Rewrite Worksheet', 'cbt'::resource_kind, 'A worksheet rewriting a fixed negative story about a partner with more recent, balanced evidence.', 'Use it to update an outdated or overly fixed negative narrative about a partner.', array['Adults']::text[], '20 minutes', 'Long relationships sometimes carry a frozen story about a partner, formed years ago, that does not update even as the partner changes. Write the old story, then gather recent evidence for and against it. The goal is not blind positivity but an accurate, current picture rather than an outdated one.', '[{"id": "f0", "type": "textarea", "label": "What is the fixed story you carry about your partner?"}, {"id": "f1", "type": "textarea", "label": "When did that story form?"}, {"id": "f2", "type": "textarea", "label": "What recent evidence supports or contradicts it?"}, {"id": "f3", "type": "textarea", "label": "What would an updated, current story sound like?"}]'::jsonb, array['relationship issues', 'core beliefs']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('interpersonal-priorities-triage-card', 'Interpersonal Priorities Triage Card', 'dbt'::resource_kind, 'A card for weighing objective, relationship and self-respect priorities before a hard conversation.', 'Use it to plan a hard conversation by weighing what matters most before it happens.', array['Adults']::text[], '15 minutes', 'Before a difficult conversation, have the client weigh three things: getting the objective outcome, protecting the relationship, and keeping their own self-respect, since a plan usually has to trade off between them. Naming the priority in advance prevents the conversation from drifting into whichever goal feels loudest in the moment. Revisit the card afterward to see how the actual conversation matched the plan.', '[{"id": "f0", "type": "textarea", "label": "What is the objective outcome you want from this conversation?"}, {"id": "f1", "type": "textarea", "label": "How important is protecting the relationship in this moment?"}, {"id": "f2", "type": "textarea", "label": "How important is your own self-respect here?"}, {"id": "f3", "type": "textarea", "label": "Given all three, what is your plan going in?"}]'::jsonb, array['relationship issues', 'interpersonal effectiveness']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('unspoken-expectations-reveal', 'Unspoken Expectations Reveal', 'couples'::resource_kind, 'An exercise where partners write and compare unspoken expectations they have been carrying.', 'Use it to surface expectations partners assume are shared but have never actually stated.', array['Couples']::text[], '25 minutes', 'Many relationship frictions trace back to an expectation one partner assumed was obvious or shared, but never actually said out loud. Have each partner write a few unspoken expectations privately before comparing, since some overlap and some genuinely surprise the other partner. Turn any real mismatches into explicit agreements rather than leaving them assumed again.', '[{"id": "f0", "type": "textarea", "label": "Write two or three expectations you have been assuming, without saying them."}, {"id": "f1", "type": "textarea", "label": "Partner: write your own, separately."}, {"id": "f2", "type": "textarea", "label": "Compare lists. What overlapped? What surprised you?"}, {"id": "f3", "type": "textarea", "label": "Which mismatch is worth turning into an explicit agreement?"}]'::jsonb, array['relationship issues', 'expectations']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('relationship-trivia-how-well-do-you-know-me-now', 'Relationship Trivia: How Well Do You Know Me Now', 'game'::resource_kind, 'A trivia game where partners guess each other''s current preferences, which often drift over time.', 'Use it to playfully update partners'' knowledge of each other, since people change over time.', array['Couples']::text[], '20 minutes', 'Long-term partners often rely on outdated knowledge of each other; this game has each partner guess the other''s current favorite, worry, or hope, then check the answer. Wrong guesses are the useful part, since they reveal where a couple''s knowledge of each other has drifted. Keep it light and curious rather than turning wrong answers into criticism.', '[{"id": "f0", "type": "textarea", "label": "Partner A guesses Partner B''s current biggest stressor, then B reveals the real answer."}, {"id": "f1", "type": "textarea", "label": "Partner B guesses Partner A''s current favorite way to relax, then A reveals the real answer."}, {"id": "f2", "type": "textarea", "label": "What surprised you about the answers?"}, {"id": "f3", "type": "textarea", "label": "What is one way to keep learning about each other going forward?"}]'::jsonb, array['relationship issues', 'connection']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('body-signals-safety-check-worksheet', 'Body Signals Safety Check Worksheet', 'worksheet'::resource_kind, 'A worksheet for noticing current body signals of safety versus alarm, in the present moment.', 'Use it to build a client''s awareness of present-moment body safety signals.', array['Adults', 'Teens']::text[], '20 minutes', 'Keep this entirely present-focused: what the body is signaling right now, not a review of past events. This is a stabilizing awareness tool, useful before or alongside grounding work, never an invitation to recount what happened. Complete this in session rather than sending it home as unsupervised work.', '[{"id": "f0", "type": "textarea", "label": "What does your body feel like right now, in this moment?"}, {"id": "f1", "type": "textarea", "label": "What tells you that you are safe right now?"}, {"id": "f2", "type": "textarea", "label": "Is there any tension or alarm present? Where?"}, {"id": "f3", "type": "textarea", "label": "What would help your body settle further right now?"}]'::jsonb, array['sexual abuse', 'grounding']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('self-blame-responsibility-sorting-worksheet', 'Self-Blame Responsibility Sorting Worksheet', 'cbt'::resource_kind, 'A worksheet sorting responsibility for what happened away from the client and onto the person responsible.', 'Use it to correct misplaced self-blame by sorting out where responsibility actually lies.', array['Adults', 'Teens']::text[], '20 minutes', 'Self-blame is extremely common after sexual abuse and rarely reflects the actual facts of responsibility. Without asking the client to describe what happened, work with the belief itself: what they believe they are responsible for, and whether that belief holds up against basic facts about consent and power. Go slowly, and stop if the client becomes flooded.', '[{"id": "f0", "type": "textarea", "label": "What do you believe you are responsible for?"}, {"id": "f1", "type": "textarea", "label": "What facts about consent or power apply here?"}, {"id": "f2", "type": "textarea", "label": "Who holds responsibility for what happened, based on those facts?"}, {"id": "f3", "type": "textarea", "label": "What is it like to consider that belief may not be accurate?"}]'::jsonb, array['sexual abuse', 'self-blame']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('present-moment-anchoring-skills-card', 'Present-Moment Anchoring Skills Card', 'dbt'::resource_kind, 'A reference card of quick anchoring skills to use when a client feels pulled out of the present.', 'Use it to give a client fast, reliable ways to return to the present moment.', array['Adults', 'Teens']::text[], '15 minutes', 'List several concrete anchoring skills, cold water, naming objects in the room, pressing feet into the floor, and have the client rate which ones work fastest for them personally. Practice each one in session so it is familiar before it is needed in a harder moment. This card is a stabilizing tool, meant for daily and in-the-moment use, not a substitute for a full safety plan.', '[{"id": "f0", "type": "textarea", "label": "Which anchoring skill worked fastest for you when we practiced it?"}, {"id": "f1", "type": "textarea", "label": "Where will you keep this card so it is easy to find?"}, {"id": "f2", "type": "textarea", "label": "What situations might call for using it?"}, {"id": "f3", "type": "textarea", "label": "What is your backup skill if the first one does not work?"}]'::jsonb, array['sexual abuse', 'grounding', 'core DBT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('partner-pacing-and-consent-check-in', 'Partner Pacing and Consent Check-In', 'couples'::resource_kind, 'A check-in structure for a couple to communicate pace and consent around physical intimacy.', 'Use it to build a clear, ongoing way for both partners to communicate about pace and consent.', array['Couples']::text[], '25 minutes', 'Build a simple, explicit way to check in before and during physical intimacy, a word or signal either partner can use without needing to explain. Keep the conversation about comfort, pace and consent, never a request to discuss what happened. The non-affected partner often needs coaching that patience here is a form of care, not a problem to solve.', '[{"id": "f0", "type": "textarea", "label": "What check-in signal or word will you use together?"}, {"id": "f1", "type": "textarea", "label": "What does \"yes, keep going\" look like for you?"}, {"id": "f2", "type": "textarea", "label": "What does \"let''s pause\" look like for you?"}, {"id": "f3", "type": "textarea", "label": "Partner: how will you respond when the pause signal comes up?"}]'::jsonb, array['sexual abuse', 'pacing']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('body-belongs-to-me-safety-rules-craft', 'Body Belongs to Me Safety Rules Craft', 'kids'::resource_kind, 'A craft where a child decorates a poster of simple body safety rules with trusted grown-ups.', 'Use it to reinforce clear, simple body safety rules a child can remember and use.', array['Children']::text[], '30 minutes', 'Keep the language simple and rule-based, my body belongs to me, I can say no, I can tell a safe grown-up, rather than any detailed or frightening explanation. If a child discloses anything during this activity, pause and follow your state''s mandatory reporting duties before continuing. Send the finished poster home and review the safe-adults list with the parent.', '[{"id": "f0", "type": "textarea", "label": "Decorate your body safety rules poster."}, {"id": "f1", "type": "textarea", "label": "Write or draw the safe grown-ups you could tell if something felt wrong."}, {"id": "f2", "type": "textarea", "label": "Practice saying \"no\" out loud."}, {"id": "f3", "type": "textarea", "label": "What is one safe grown-up you could go to today?"}]'::jsonb, array['sexual abuse', 'children', 'grounding']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('coping-skills-cost-and-access-matrix', 'Coping Skills Cost and Access Matrix', 'worksheet'::resource_kind, 'A worksheet sorting a client''s coping skills by how much effort they take and how accessible they are.', 'Use it to build a realistic coping plan sorted by effort and accessibility, not just preference.', array['Adults', 'Teens']::text[], '20 minutes', 'A coping skill that is technically effective but requires too much setup often goes unused in a real hard moment. Sort skills into a simple grid by effort required and how accessible they are anywhere, anytime versus only at home. Make sure at least a few low-effort, high-access options are always on hand.', '[{"id": "f0", "type": "textarea", "label": "List coping skills that work for you, regardless of effort."}, {"id": "f1", "type": "textarea", "label": "Which ones are low effort and available almost anywhere?"}, {"id": "f2", "type": "textarea", "label": "Which ones take more setup or only work at home?"}, {"id": "f3", "type": "textarea", "label": "What is your go-to option for a hard moment in public?"}]'::jsonb, array['coping skills', 'planning']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('unhelpful-coping-pattern-swap-worksheet', 'Unhelpful Coping Pattern Swap Worksheet', 'cbt'::resource_kind, 'A worksheet identifying an unhelpful coping habit and planning a healthier swap for the same function.', 'Use it to replace an unhelpful coping habit with one that serves the same function.', array['Adults', 'Teens']::text[], '20 minutes', 'Rather than simply telling a client to stop an unhelpful habit, identify what function it serves, distraction, comfort, control, and find a swap that serves the same function without the same cost. A direct swap tends to stick better than a replacement chosen at random. Expect some trial and error before finding a good match.', '[{"id": "f0", "type": "textarea", "label": "What is a coping habit you would like to change?"}, {"id": "f1", "type": "textarea", "label": "What function does it serve, like comfort or distraction?"}, {"id": "f2", "type": "textarea", "label": "What is another way to meet that same function?"}, {"id": "f3", "type": "textarea", "label": "How did trying the swap go?"}]'::jsonb, array['coping skills', 'behavioral']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('coping-with-willingness-not-elimination-practice', 'Coping With Willingness, Not Elimination Practice', 'act'::resource_kind, 'An exercise reframing coping skills as tools for carrying discomfort, not eliminating it.', 'Use it to shift the goal of coping from eliminating discomfort to carrying it workably.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients sometimes judge a coping skill as failing whenever discomfort remains afterward, when many skills are meant to help a person function alongside discomfort, not erase it. Reframe the goal explicitly: did this skill help you keep moving with the discomfort present, rather than did it make the discomfort disappear. This often reduces frustration with skills that were actually working.', '[{"id": "f0", "type": "textarea", "label": "What coping skill have you judged as \"not working\"?"}, {"id": "f1", "type": "textarea", "label": "Did it help you keep functioning, even with discomfort still present?"}, {"id": "f2", "type": "textarea", "label": "What would \"success\" look like if the goal is carrying discomfort, not erasing it?"}, {"id": "f3", "type": "textarea", "label": "Does that change how you feel about the skill?"}]'::jsonb, array['coping skills', 'acceptance', 'core ACT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('personal-crisis-skill-hierarchy-card', 'Personal Crisis Skill Hierarchy Card', 'dbt'::resource_kind, 'A card ranking a client''s coping skills from mild distress up through crisis-level distress.', 'Use it to give a client a ranked plan of skills matched to distress intensity, including crisis level.', array['Adults', 'Teens']::text[], '20 minutes', 'Build the hierarchy together from mild through severe distress, and for the top of the scale, include a plan for reaching out, a trusted person, a crisis line, or 988, which can be called or texted. Complete this in session, walking through what the client would actually do at each level, rather than assigning it as homework. Keep the finished card somewhere easy to find.', '[{"id": "f0", "type": "textarea", "label": "What skill works for mild distress, 1 to 3 out of 10?"}, {"id": "f1", "type": "textarea", "label": "What skill works for moderate distress, 4 to 6?"}, {"id": "f2", "type": "textarea", "label": "What skill works for high distress, 7 to 8?"}, {"id": "f3", "type": "textarea", "label": "At a 9 or 10, or if you are unsafe, who will you call or text, including 988 if needed?"}]'::jsonb, array['coping skills', 'distress tolerance', 'crisis']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('coping-skills-speed-sort-game', 'Coping Skills Speed Sort Game', 'game'::resource_kind, 'A timed sorting game racing to sort coping skill cards into correct categories before time runs out.', 'Use it to build quick, confident recall of which coping skills fit which category.', array['Teens', 'Children', 'Groups']::text[], '15 minutes', 'Shuffle a deck of coping skill cards and set a timer for sorting them into categories like calming, distracting, and connecting with others. Speed adds a playful pressure that helps skills become more automatic to recall. Play multiple rounds, timing improvement rather than perfection, and debrief on any cards that were genuinely tricky to sort.', '[{"id": "f0", "type": "textarea", "label": "Sort your coping skill cards into categories before time runs out."}, {"id": "f1", "type": "textarea", "label": "How long did it take you?"}, {"id": "f2", "type": "textarea", "label": "Which card was hardest to sort? Why?"}, {"id": "f3", "type": "textarea", "label": "Which category has the fewest cards? What could you add?"}]'::jsonb, array['coping skills', 'group']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('phobia-avoidance-ripple-effect-worksheet', 'Phobia Avoidance Ripple Effect Worksheet', 'worksheet'::resource_kind, 'A worksheet mapping how avoiding a feared object or situation has quietly shrunk a client''s life.', 'Use it to make the widening cost of avoidance visible beyond the feared situation itself.', array['Adults', 'Teens']::text[], '20 minutes', 'A phobia''s cost often extends well past the feared object itself, into missed events, altered routes, or avoided plans that ripple outward. List the direct avoidance first, then trace what it has affected further out. Seeing the full ripple, not just the original fear, often builds stronger motivation for exposure work than the fear alone.', '[{"id": "f0", "type": "textarea", "label": "What do you avoid directly because of this fear?"}, {"id": "f1", "type": "textarea", "label": "What has that avoidance affected beyond the fear itself?"}, {"id": "f2", "type": "textarea", "label": "And beyond that?"}, {"id": "f3", "type": "textarea", "label": "What would you want back if the ripple effect were smaller?"}]'::jsonb, array['phobias', 'avoidance']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('fear-probability-estimate-worksheet', 'Fear Probability Estimate Worksheet', 'cbt'::resource_kind, 'A worksheet comparing a client''s estimated probability of the feared outcome with a realistic estimate.', 'Use it to challenge an inflated probability estimate of the feared outcome actually occurring.', array['Adults', 'Teens']::text[], '20 minutes', 'Phobias often inflate the actual likelihood of harm far beyond what is realistic. Have the client estimate the probability of the feared outcome, then walk through available information to build a more realistic estimate, and revisit both numbers after any approach step is attempted. The gap between feared and actual probability tends to shrink with repeated practice.', '[{"id": "f0", "type": "textarea", "label": "What is the feared outcome?"}, {"id": "f1", "type": "textarea", "label": "What probability do you give it happening, 0 to 100?"}, {"id": "f2", "type": "textarea", "label": "What does the available information suggest is more realistic?"}, {"id": "f3", "type": "textarea", "label": "After trying an approach step, how did the numbers compare?"}]'::jsonb, array['phobias', 'core CBT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('willing-to-feel-afraid-and-approach-practice', 'Willing to Feel Afraid and Approach Practice', 'act'::resource_kind, 'A willingness exercise separating the presence of fear from the decision to approach anyway.', 'Use it to practice approaching a feared situation while fear is still present, not after it is gone.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients often wait for fear to go away before approaching a feared situation, which can delay action indefinitely. Practice the distinction directly: fear can be present at the same time as a chosen approach step, rather than one needing to precede the other. Use a low-stakes approach step to practice this distinction concretely.', '[{"id": "f0", "type": "textarea", "label": "What approach step are you willing to try, fear and all?"}, {"id": "f1", "type": "textarea", "label": "How much fear do you expect to feel, 0 to 10?"}, {"id": "f2", "type": "textarea", "label": "Try the step while making room for that fear. What happened?"}, {"id": "f3", "type": "textarea", "label": "What did you learn about acting alongside fear rather than after it?"}]'::jsonb, array['phobias', 'willingness', 'core ACT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('brave-steps-sticker-map-craft', 'Brave Steps Sticker Map Craft', 'kids'::resource_kind, 'A craft where a child builds and decorates a map of approach steps toward a feared object.', 'Use it to give a child a visual, rewarding path through graded approach steps.', array['Children']::text[], '30 minutes', 'Build the map together as a path with a handful of steps, from easiest to the goal step, and let the child decorate it and choose stickers to earn along the way. A parent should be part of planning how and when steps get practiced at home, with praise for effort, not just success. Keep the pace led by the child''s readiness, not a fixed schedule.', '[{"id": "f0", "type": "textarea", "label": "Draw your path with a few steps from easy to brave."}, {"id": "f1", "type": "textarea", "label": "Decorate your map."}, {"id": "f2", "type": "textarea", "label": "Which step will you try first?"}, {"id": "f3", "type": "textarea", "label": "Parent: how will you support and celebrate each step?"}]'::jsonb, array['phobias', 'children']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('feared-object-fact-hunt-game', 'Feared Object Fact Hunt Game', 'game'::resource_kind, 'A game where players search for and share accurate facts about a feared object or animal.', 'Use it to build accurate knowledge about a feared object in a playful, curious format.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Have players find or share interesting, accurate facts about the feared object or animal, taking turns presenting one fact at a time. Curiosity and fact-finding can loosen a fear''s grip in a way that stays lighter than direct exposure alone. This works especially well for children fearful of animals or natural phenomena.', '[{"id": "f0", "type": "textarea", "label": "Share one fact you found about the feared object or animal."}, {"id": "f1", "type": "textarea", "label": "What surprised you about that fact?"}, {"id": "f2", "type": "textarea", "label": "Did learning it change how scary the object feels, even a little?"}, {"id": "f3", "type": "textarea", "label": "What is one more fact you would like to learn?"}]'::jsonb, array['phobias', 'psychoeducation', 'group']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('appearance-free-day-reflection-worksheet', 'Appearance-Free Day Reflection Worksheet', 'worksheet'::resource_kind, 'A worksheet reflecting on a day spent minimizing appearance-checking behaviors.', 'Use it to build awareness of how much attention appearance normally takes up.', array['Adults', 'Teens']::text[], 'One day, plus reflection', 'Ask the client to notice, for one day, how often attention pulls toward appearance, mirrors, reflections, comparing to others, without any requirement to change the behavior yet. This is an awareness exercise, not a challenge to pass or fail, and some clients find the sheer frequency surprising once counted. Use the reflection to choose one behavior to work on next.', '[{"id": "f0", "type": "textarea", "label": "Roughly how many times did your attention pull toward appearance today?"}, {"id": "f1", "type": "textarea", "label": "What situations triggered it most?"}, {"id": "f2", "type": "textarea", "label": "What did you notice about how that attention affected your mood?"}, {"id": "f3", "type": "textarea", "label": "What is one behavior you would like to work on reducing?"}]'::jsonb, array['body image', 'self-monitoring']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('appearance-rule-origin-worksheet', 'Appearance Rule Origin Worksheet', 'cbt'::resource_kind, 'A worksheet tracing where a rigid appearance-related rule or standard originally came from.', 'Use it to examine a rigid appearance rule by tracing its origin and current cost.', array['Adults', 'Teens']::text[], '20 minutes', 'Rigid appearance rules, like needing to look a certain way before leaving the house, usually have a traceable origin, a comment, a comparison, a message absorbed early. Naming the origin often loosens the rule''s grip, since it reveals the rule as learned rather than an objective truth. Keep the conversation on function and rules, never on specific numbers or measurements.', '[{"id": "f0", "type": "textarea", "label": "What is a rigid rule you hold about your appearance?"}, {"id": "f1", "type": "textarea", "label": "Where do you think that rule first came from?"}, {"id": "f2", "type": "textarea", "label": "What does following that rule cost you day to day?"}, {"id": "f3", "type": "textarea", "label": "What would a more flexible version of that rule look like?"}]'::jsonb, array['body image', 'core beliefs']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('body-as-instrument-practice', 'Body as Instrument Practice', 'act'::resource_kind, 'An exercise shifting focus from how the body looks to what the body allows a client to do.', 'Use it to shift attention from appearance toward the body''s function in a client''s life.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to list what their body allows them to do, hug someone, walk outside, laugh, rather than how it looks. This keeps the exercise strictly on function and capability, never on weight, size, or appearance. Some clients find this shift difficult at first; normalize that it takes repeated practice to redirect attention this way.', '[{"id": "f0", "type": "textarea", "label": "What does your body allow you to do that matters to you?"}, {"id": "f1", "type": "textarea", "label": "What has your body carried you through?"}, {"id": "f2", "type": "textarea", "label": "How does focusing on function feel different from focusing on appearance?"}, {"id": "f3", "type": "textarea", "label": "What is one way to notice your body''s function this week?"}]'::jsonb, array['body image', 'values', 'core ACT']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('supporting-body-image-without-commenting-conversation', 'Supporting Body Image Without Commenting Conversation', 'couples'::resource_kind, 'A conversation guide helping a partner support body image struggles without commenting on appearance.', 'Use it to agree on supportive language that leaves appearance and food entirely out of it.', array['Couples']::text[], '20 minutes', 'Well-meaning comments about appearance, even compliments, can reinforce a preoccupation with how the body looks. Coach the supporting partner toward comments about presence, effort or connection instead, and explicitly agree to keep appearance and food out of the conversation altogether. Revisit the agreement if old habits creep back in.', '[{"id": "f0", "type": "textarea", "label": "What kinds of comments about your appearance feel unhelpful, even if well meant?"}, {"id": "f1", "type": "textarea", "label": "What kind of support actually feels helpful?"}, {"id": "f2", "type": "textarea", "label": "Partner: what will you say instead, going forward?"}, {"id": "f3", "type": "textarea", "label": "What will you both do if an old habit slips back in?"}]'::jsonb, array['body image', 'support']::text[], '2026-09-19T15:00:00+00:00'::timestamptz),
  ('all-the-things-my-body-can-do-craft', 'All the Things My Body Can Do Craft', 'kids'::resource_kind, 'A craft where a child draws and lists all the things their body can do, like run, hug and draw.', 'Use it to build a child''s sense of their body as capable, not something to judge by looks.', array['Children']::text[], '25 minutes', 'Have the child trace or draw an outline of themselves and fill it with drawings of activities their body lets them do, playing, hugging, jumping, drawing itself. Keep the activity strictly about capability and fun, with no reference to size, weight or how bodies look. Parents can extend this at home by noticing and naming what the child''s body does well.', '[{"id": "f0", "type": "textarea", "label": "Draw an outline of yourself."}, {"id": "f1", "type": "textarea", "label": "Fill it with pictures of things your body lets you do."}, {"id": "f2", "type": "textarea", "label": "Which of these is your favorite thing your body can do?"}, {"id": "f3", "type": "textarea", "label": "What is something new you would like your body to help you try?"}]'::jsonb, array['body image', 'children']::text[], '2026-09-19T15:00:00+00:00'::timestamptz)
